import basics from "./basics";
import basics2 from "./basics-2";

export default {
  id: "os",
  name: "Operating Systems",
  blurb: "The layer between you and the metal — processes, memory, files, and concurrency. Understand how the OS manages resources and you understand every program's environment.",
  glyph: "⚙",
  tags: ["Systems", "Kernel", "Concurrency", "Memory"],
  topics: [basics, ...basics2,
    { id: "intro-to-os", title: "Introduction to Operating Systems", difficulty: "easy", definition: "An operating system is system software that manages computer hardware and software resources, providing common services for programs. It acts as an intermediary between users and hardware — managing the CPU, memory, storage, and I/O devices, and providing abstractions like processes, files, and virtual memory.",
      coreUnderstanding: "The OS is the foundation beneath every program you run. It manages the CPU (who runs when), memory (who gets what address space), storage (files and directories), and I/O devices (keyboard, screen, network). It provides abstractions — processes (virtual CPU), virtual memory (infinite RAM illusion), files (named disk blocks) — that make programming practical. Without an OS, each program would need to manage hardware directly, which is impractical and dangerous.",
      howItWorks: "1. Boot: the BIOS/UEFI loads the OS kernel from disk into RAM.\n2. The kernel runs in kernel mode (full hardware access) and manages all resources.\n3. User programs run in user mode (restricted) and request services via system calls.\n4. The scheduler time-slices the CPU among processes (context switching).\n5. The memory manager gives each process a virtual address space (paging/swapping).\n6. The file system organizes disk data into files and directories.\n7. Device drivers translate generic I/O requests into hardware-specific commands.\n8. Interrupts: hardware signals (timer, disk done) cause the OS to take over briefly.",
      codeExamples: [{ lang: "bash", code: "# View running processes (the OS's process table)\nps aux | head\n\n# View memory usage (the OS's memory management)\nfree -h\n#               total   used   free  shared  buff/cache  available\n# Mem:           16Gi   4Gi    8Gi   256Mi   4Gi          11Gi\n\n# View open files (the OS's file table)\nlsof | head\n\n# The kernel itself\nuname -r  # 6.5.0-21-generic\n\n# System calls a program makes\nstrace echo hello 2>&1 | head\n# write(1, \"hello\\n\", 6) = 6", output: "(OS info)", note: "The OS manages CPU (scheduling), memory (virtual memory), storage (file system), and I/O (device drivers). It provides abstractions (processes, files, virtual memory) that make programming practical." }],
      marginNotes: ["The OS provides abstractions: processes (virtual CPU), virtual memory (infinite RAM illusion), files (named disk blocks). These make programming practical — without them, you'd manage hardware directly.", "The kernel runs in kernel mode (full hardware access). User programs run in user mode (restricted). System calls are the bridge — they trigger a context switch into kernel mode.", "Key OS resources: CPU (scheduling), memory (allocation/paging), disk (file system), I/O devices (drivers). The OS manages all of these and provides fair, safe access to programs."],
      commonMistakes: ["Confusing the OS with the kernel — the kernel is the core of the OS, but the OS also includes system libraries, utilities, and the shell.", "Thinking the OS 'runs programs' directly — it time-slices the CPU among many processes, creating the illusion of simultaneous execution."],
      relatedTopics: ["OS Structure & Kernel", "System Calls", "User Mode vs Kernel Mode"],
      externalLinks: [{ label: "OS Concepts (Wiki)", url: "https://en.wikipedia.org/wiki/Operating_system" }],
      mcqs: [{ question: "What is the primary role of an operating system?", options: ["To compile code", "To manage hardware resources and provide abstractions for programs", "To browse the internet", "To edit text files"], answer: 1, explanations: ["Compilers compile code, not the OS.", "Correct — the OS manages CPU, memory, storage, and I/O, providing abstractions like processes, files, and virtual memory that make programming practical.", "Browsers are application programs.", "Text editors are application programs."], difficulty: "easy" }] },
    { id: "os-structure", title: "OS Structure & Kernel", difficulty: "medium", definition: "The kernel is the core of the OS, running in privileged (kernel) mode with full hardware access. Monolithic kernels (Linux) put all services in kernel space for speed. Microkernels (MINIX) keep the kernel minimal and run services as user-space processes for modularity. Hybrid kernels (Windows, macOS) blend both approaches.",
      coreUnderstanding: "The kernel is the heart of the OS — the part that runs in kernel mode with full hardware access. Three architectures: (1) Monolithic (Linux) — all OS services (scheduling, file system, drivers) run in kernel space. Fast (no mode switches) but large and harder to debug. (2) Microkernel (MINIX, QNX) — the kernel is minimal (IPC, scheduling, basic memory). Services (file system, drivers) run as user-space processes. More modular and reliable but slower (IPC overhead). (3) Hybrid (Windows, macOS) — a compromise: some services in kernel, some in user space.",
      howItWorks: "1. Monolithic: all services (scheduler, file system, network stack, drivers) in kernel space. Communication is fast (direct function calls). A bug in any service can crash the entire kernel.\n2. Microkernel: kernel has only IPC, scheduling, and basic memory management. Services communicate via message passing (IPC). Slower but more reliable — a crashing driver doesn't crash the kernel.\n3. Hybrid: combines both. Core services in kernel (performance), some services in user space (modularity). Windows NT and macOS XNU are hybrids.\n4. Kernel mode: full hardware access. User mode: restricted. System calls switch from user to kernel mode.\n5. Loadable modules: Linux supports dynamically loading kernel modules (drivers) without recompiling.",
      codeExamples: [{ lang: "bash", code: "# Check if you're running a monolithic or modular kernel\nlsmod | head  # lists loaded kernel modules (Linux is modular)\n\n# Kernel version\nuname -r  # 6.5.0-21-generic\n\n# View kernel modules\ncat /proc/modules | head\n# nfnetlink 16384 0 - Live 0x...\n# bluetooth 614400 0 - Live 0x...\n\n# The kernel itself\nls /boot/vmlinuz-*  # the kernel binary\n\n# Microkernel example: MINIX 3\n# Hybrid: Windows NT (ntoskrnl.exe), macOS (XNU: Mach + BSD)", output: "(kernel info)", note: "Monolithic (Linux): all services in kernel — fast but large. Microkernel (MINIX): minimal kernel, services in user space — modular but slower. Hybrid (Windows, macOS): compromise. Kernel mode = full hardware access." }],
      marginNotes: ["Monolithic kernels (Linux) are fast — all services are in kernel space, so communication is direct function calls. But a bug in any service can crash the entire kernel.", "Microkernels (MINIX) are more reliable — services run as user-space processes, so a crashing driver doesn't crash the kernel. But IPC (message passing) is slower than direct function calls.", "Linux is technically a 'modular monolithic' kernel — it's monolithic (all services in kernel space) but supports loading/unloading modules (drivers) dynamically."],
      commonMistakes: ["Thinking microkernels are always better — they're more modular but slower due to IPC overhead. The performance cost is why most production OSes use monolithic or hybrid designs.", "Confusing the kernel with the OS — the kernel is the core of the OS, but the OS also includes system libraries, utilities, and the shell."],
      relatedTopics: ["Introduction to Operating Systems", "System Calls", "User Mode vs Kernel Mode"],
      externalLinks: [{ label: "Kernel (Wiki)", url: "https://en.wikipedia.org/wiki/Kernel_(operating_system)" }],
      mcqs: [{ question: "What is the main advantage of a monolithic kernel?", options: ["Modularity", "Speed — all services in kernel space, direct function calls", "Security", "Small size"], answer: 1, explanations: ["Modularity is a microkernel advantage.", "Correct — monolithic kernels (Linux) put all services in kernel space. Communication is via direct function calls (fast). The trade-off: a bug in any service can crash the entire kernel.", "Security is better in microkernels.", "Monolithic kernels are large."], difficulty: "medium" }] },
    { id: "system-calls", title: "System Calls", difficulty: "medium", definition: "A system call is the programmatic way a process requests a service from the kernel — the boundary between user mode and kernel mode. Examples: open(), read(), write(), fork(), exec(), exit(). Each syscall triggers a context switch (trap) into kernel mode. System calls are expensive (context switch overhead), so programs minimize them.",
      coreUnderstanding: "A system call (syscall) is how a user program asks the kernel to do something it can't do itself (I/O, process creation, memory allocation). The user program executes a special instruction (trap/syscall) that switches the CPU from user mode to kernel mode. The kernel validates the request, performs the operation, and returns the result. This mode switch is expensive (saving/restoring registers, security checks), so programs minimize syscalls. Examples: read(), write(), open(), fork(), exec(), exit(), brk(), mmap().",
      howItWorks: "1. User program calls a library function (e.g., printf -> write).\n2. The library function puts the syscall number and arguments in registers.\n3. The program executes a trap/syscall instruction (e.g., int 0x80 on x86, syscall on x86-64).\n4. The CPU switches from user mode to kernel mode (privilege escalation).\n5. The kernel looks up the syscall number in the syscall table and calls the corresponding kernel function.\n6. The kernel validates arguments (security: can this process access this file?).\n7. The kernel performs the operation and puts the result in a register.\n8. The CPU switches back to user mode, and the program continues with the result.\n9. Cost: each syscall involves a mode switch (user -> kernel -> user) — expensive (~1 microsecond).",
      codeExamples: [{ lang: "c", code: "#include <stdio.h>\n#include <unistd.h>\n#include <fcntl.h>\n\nint main() {\n    // System calls: open, read, write, close\n    int fd = open(\"file.txt\", O_RDONLY);  // syscall\n    char buf[100];\n    int n = read(fd, buf, 100);          // syscall\n    write(1, buf, n);                    // syscall (1 = stdout)\n    close(fd);                            // syscall\n    return 0;\n}\n\n// Process syscalls\n// pid_t pid = fork();    // create a child process (syscall)\n// execvp(\"ls\", args);    // replace process image (syscall)\n// exit(0);               // terminate (syscall)\n\n// Memory syscalls\n// void *p = sbrk(4096);  // extend heap (syscall)\n// void *m = mmap(...);   // map memory (syscall)", output: "(file content)", note: "System calls are the boundary between user mode and kernel mode. Each syscall triggers a mode switch (expensive). Examples: open, read, write, fork, exec, exit, mmap. Programs minimize syscalls for performance." }],
      marginNotes: ["System calls are expensive (~1 microsecond each) because they involve a mode switch (user -> kernel -> user), saving/restoring registers, and security checks. Programs that make many syscalls (e.g., reading a file byte by byte) are slow — use buffered I/O to batch reads.", "The syscall interface is the API between user programs and the kernel. POSIX standardizes it (open, read, write, fork, exec) across Unix-like systems. Windows has its own Win32 API.", "Common syscalls: I/O (open, read, write, close), process (fork, exec, exit, wait), memory (brk, mmap, munmap), IPC (pipe, socket, shmget), file system (mkdir, chdir, stat)."],
      commonMistakes: ["Making too many syscalls (e.g., reading a file byte by byte with read(fd, &c, 1)) — extremely slow. Use buffered I/O (fread, BufferedReader) to batch reads.", "Forgetting that syscall arguments are validated by the kernel — a bad pointer passed to read() causes the kernel to return an error (EFAULT), not a segfault."],
      relatedTopics: ["User Mode vs Kernel Mode", "Context Switching", "OS Structure & Kernel"],
      externalLinks: [{ label: "System Calls (Wiki)", url: "https://en.wikipedia.org/wiki/System_call" }],
      mcqs: [{ question: "Why are system calls expensive?", options: ["They use a lot of memory", "Each syscall involves a mode switch (user to kernel and back), saving/restoring registers, and security checks", "They are slower than regular function calls due to network latency", "They require compilation"], answer: 1, explanations: ["Memory is not the main cost.", "Correct — each syscall involves a mode switch (user mode to kernel mode and back), saving/restoring CPU registers, and security argument validation. This overhead is ~1 microsecond per call. Programs minimize syscalls (e.g., buffered I/O) for performance.", "No network involved — it's a local CPU operation.", "No compilation at runtime."], difficulty: "medium" }] },
    { id: "user-kernel-mode", title: "User Mode vs Kernel Mode", difficulty: "medium", definition: "Modern CPUs run in at least two privilege levels: user mode (restricted, cannot access hardware directly) and kernel mode (full access). User programs run in user mode; the OS kernel runs in kernel mode. Transitions happen via system calls, interrupts, or exceptions. This isolation protects the system from buggy or malicious programs.",
      coreUnderstanding: "CPUs have privilege levels (rings) to protect the system. User mode (ring 3): restricted — cannot access hardware, I/O ports, or memory management registers directly. Kernel mode (ring 0): full access to all hardware and memory. User programs run in user mode; if they try to do something privileged (access hardware, modify page tables), the CPU blocks it and raises an exception. The kernel (kernel mode) handles the exception, performs the operation if legitimate, or kills the program if malicious. This isolation is why a crashing user program doesn't crash the entire system.",
      howItWorks: "1. Ring 0 (kernel mode): full hardware access. The OS kernel runs here. Can execute any instruction, access any memory.\n2. Ring 3 (user mode): restricted. User programs run here. Cannot execute privileged instructions (IN, OUT, HALT, modify page tables) or access kernel memory.\n3. Transition to kernel mode: system calls (trap instruction), interrupts (hardware signals), exceptions (divide by zero, page fault).\n4. Transition back: the kernel returns control to the user program (iret/sysret instruction), switching back to user mode.\n5. Protection: if a user program tries a privileged instruction, the CPU raises a protection fault -> the kernel handles it (usually kills the program).\n6. Virtual memory: each process has its own address space. The kernel's pages are marked as supervisor-only — user programs can't read or write kernel memory.",
      codeExamples: [{ lang: "c", code: "// In user mode, you CANNOT do these directly:\n// - Access I/O ports (inb, outb)\n// - Modify page tables\n// - Disable interrupts (cli)\n// - Access hardware registers directly\n\n// Instead, you ask the kernel via system calls:\n#include <unistd.h>\n\nint main() {\n    // write() is a system call — the kernel does the I/O for you\n    write(1, \"Hello\\n\", 6);  // 1 = stdout\n    \n    // If you tried to write to the screen directly:\n    // outb(0x3F8, 'H');  // CRASH! Privileged instruction in user mode\n    \n    return 0;\n}\n\n// Ring model:\n// Ring 0: Kernel (full access)\n// Ring 1: Device drivers (rarely used)\n// Ring 2: System services (rarely used)\n// Ring 3: User programs (restricted)", output: "Hello", note: "User mode (ring 3) = restricted, kernel mode (ring 0) = full access. System calls, interrupts, and exceptions trigger transitions. This isolation protects the system from buggy or malicious programs." }],
      marginNotes: ["The ring model (x86): Ring 0 (kernel), Ring 3 (user). Rings 1 and 2 exist but are rarely used. The key boundary is between Ring 0 (full access) and Ring 3 (restricted).", "If a user program tries a privileged instruction (accessing I/O ports, modifying page tables), the CPU raises a protection fault. The kernel handles it — usually by sending SIGSEGV to the program (crashing it).", "Virtual memory adds another layer: kernel pages are marked supervisor-only. Even if a user program has the right pointer, it can't read or write kernel memory — the MMU blocks it."],
      commonMistakes: ["Thinking user programs can access hardware directly — they can't. They must go through the kernel via system calls. This is a security feature, not a limitation.", "Confusing user/kernel mode with process isolation — they're related but different. User/kernel mode is about privilege levels; process isolation is about separate address spaces."],
      relatedTopics: ["System Calls", "OS Structure & Kernel", "Context Switching"],
      externalLinks: [{ label: "Protection Ring (Wiki)", url: "https://en.wikipedia.org/wiki/Protection_ring" }],
      mcqs: [{ question: "What happens if a user-mode program tries to execute a privileged instruction?", options: ["It works fine", "The CPU raises a protection fault — the kernel handles it (usually crashes the program)", "It is silently ignored", "The program is promoted to kernel mode"], answer: 1, explanations: ["It doesn't work in user mode.", "Correct — the CPU blocks privileged instructions in user mode and raises a protection fault (exception). The kernel handles it, usually by sending a signal (SIGSEGV) to the program, crashing it. This protects the system from buggy or malicious code.", "It's not ignored — it's blocked.", "The program is not promoted — it's blocked."], difficulty: "medium" }] },
    { id: "process-concept", title: "Processes & Process Control Block", difficulty: "medium", definition: "A process is a program in execution — an instance of a program with its own memory space, registers, and open files. The OS tracks each process in a Process Control Block (PCB), storing the process ID, state, program counter, registers, memory limits, and open file table. The PCB is the kernel's bookkeeping for a process.",
      coreUnderstanding: "A process is a program in execution — it has its own address space (memory), open files, register values, and execution state. The OS represents each process with a Process Control Block (PCB), a data structure containing everything the OS needs to manage the process: PID, state (ready/running/blocked), program counter (where it's executing), CPU registers, memory management info (page tables), and open file descriptors. The PCB is how the OS saves and restores a process during context switches — it stores the process's complete state so it can be resumed later.",
      howItWorks: "1. Process creation: fork() creates a copy of the calling process. exec() replaces the process image with a new program.\n2. PCB contents: PID (process ID), state (new/ready/running/blocked/terminated), PC (program counter), registers, memory limits, open file table, scheduling info (priority, time slice).\n3. Address space: each process has its own virtual address space (code, data, heap, stack). Processes are isolated — one can't access another's memory.\n4. Context switch: the OS saves the current process's state (registers, PC) into its PCB, loads the next process's state from its PCB, and resumes it.\n5. Process tree: processes form a tree. init (PID 1) is the root. fork() creates children. wait() waits for children to finish.\n6. Process termination: exit() terminates the process. The PCB is freed (after the parent calls wait()).",
      codeExamples: [{ lang: "c", code: "#include <stdio.h>\n#include <unistd.h>\n#include <sys/wait.h>\n\nint main() {\n    pid_t pid = fork();  // create a child process\n    \n    if (pid == 0) {\n        // Child process\n        printf(\"Child: PID=%d, Parent PID=%d\\n\", getpid(), getppid());\n        execlp(\"/bin/ls\", \"ls\", NULL);  // replace with ls\n    } else if (pid > 0) {\n        // Parent process\n        printf(\"Parent: PID=%d, Child PID=%d\\n\", getpid(), pid);\n        wait(NULL);  // wait for child to finish\n        printf(\"Child done\\n\");\n    }\n    return 0;\n}\n\n// PCB contains:\n// - PID: unique process ID\n// - State: ready/running/blocked\n// - PC: program counter (where it's executing)\n// - Registers: CPU register snapshot\n// - Memory info: page tables, memory limits\n// - Open files: file descriptor table\n// - Scheduling info: priority, CPU time used", output: "Parent: PID=100, Child PID=101\nChild: PID=101, Parent PID=100\nfile1.txt  file2.txt\nChild done", note: "A process is a program in execution with its own memory space. The PCB stores everything the OS needs: PID, state, PC, registers, memory info, open files. Context switches save/restore the PCB." }],
      marginNotes: ["A process is NOT the same as a program. A program is a passive file on disk. A process is an active instance — it has memory, open files, registers, and a state. One program can have many processes (e.g., multiple terminals running bash).", "The PCB is the kernel's bookkeeping for a process. During a context switch, the OS saves the current process's register values and PC into its PCB, then loads the next process's PCB. This is what makes context switching expensive.", "Process vs Thread: a process has its own address space. Threads within a process share the same address space but have separate stacks and registers. Threads are lighter weight than processes."],
      commonMistakes: ["Confusing process with program — a program is a file, a process is an instance in execution. One program can create many processes.", "Confusing process with thread — processes have separate address spaces; threads share an address space. Context switching between threads is cheaper than between processes."],
      relatedTopics: ["Process States & Transitions", "Context Switching", "CPU Scheduling & Scheduler"],
      externalLinks: [{ label: "Process (Wiki)", url: "https://en.wikipedia.org/wiki/Process_(computing)" }],
      mcqs: [{ question: "What is stored in a Process Control Block (PCB)?", options: ["Only the process name", "PID, state, program counter, registers, memory info, open files — the OS's complete bookkeeping for the process", "Only the memory address", "Only the process priority"], answer: 1, explanations: ["The PCB contains much more than the name.", "Correct — the PCB stores everything the OS needs to manage a process: PID, state (ready/running/blocked), program counter, CPU registers, memory management info (page tables), open file table, and scheduling info (priority, CPU time). It's saved/restored during context switches.", "Memory is part of it, but not all.", "Priority is part of it, but not all."], difficulty: "medium" }] },
    { id: "process-states", title: "Process States & Transitions", difficulty: "easy", definition: "A process cycles through states: New (being created), Ready (waiting for CPU), Running (executing on CPU), Waiting/Blocked (waiting for I/O or event), Terminated (finished). The scheduler moves processes between Ready and Running. I/O requests move Running→Blocked; I/O completion moves Blocked→Ready. Understanding this cycle is key to understanding scheduling.",
      coreUnderstanding: "A process's lifecycle is a state machine. New: process is being created (fork). Ready: process is in the ready queue, waiting for the CPU. Running: process is executing on the CPU. Blocked/Waiting: process is waiting for I/O or an event (can't run until it completes). Terminated: process has finished (exit). The scheduler moves processes between Ready and Running (dispatch and preempt). I/O requests move Running to Blocked. I/O completion moves Blocked to Ready. On multi-core systems, multiple processes can be Running simultaneously (one per core).",
      howItWorks: "1. New -> Ready: process creation (fork) completes, process is ready to run.\n2. Ready -> Running: the scheduler dispatches the process to a CPU core.\n3. Running -> Ready: the scheduler preempts the process (time slice expired or higher-priority process arrived).\n4. Running -> Blocked: the process requests I/O (read, write) or waits for an event (lock, signal). It gives up the CPU.\n5. Blocked -> Ready: the I/O completes or the event occurs. The process is ready to run again.\n6. Running -> Terminated: the process finishes (exit) or is killed.\n7. On multi-core: multiple processes can be Running simultaneously (one per core). The scheduler manages the ready queue.\n8. Context switch: when the scheduler switches from one process to another, it saves the old process's state (PCB) and loads the new one.",
      codeExamples: [{ lang: "text", code: "Process State Diagram:\n\n  New ──> Ready ──> Running ──> Terminated\n            ^   ^       |\n            |   |       v\n            |   └── Preempt (time slice expired)\n            |               \n            └── Blocked <── I/O or event wait\n                  |\n                  v\n               Ready <── I/O or event complete\n\nStates:\n  New:        being created (fork)\n  Ready:      in ready queue, waiting for CPU\n  Running:    executing on a CPU core\n  Blocked:    waiting for I/O or event\n  Terminated: finished (exit)\n\nTransitions:\n  New -> Ready:       creation complete\n  Ready -> Running:   scheduler dispatches\n  Running -> Ready:   preempted (time slice)\n  Running -> Blocked: I/O request\n  Blocked -> Ready:   I/O complete\n  Running -> Terminated: exit()", output: "(state diagram)", note: "Process states: New, Ready, Running, Blocked, Terminated. Scheduler dispatches (Ready->Running) and preempts (Running->Ready). I/O requests cause Running->Blocked. I/O completion causes Blocked->Ready." }],
      marginNotes: ["A process in Blocked state is NOT using the CPU — it's waiting for I/O or an event. This is why I/O-bound processes don't waste CPU: they give up the CPU while waiting, letting other processes run.", "Preemption: the scheduler can force a Running process back to Ready (time slice expired or higher-priority process arrived). This is preemptive scheduling. Non-preemptive scheduling lets a process run until it blocks or finishes.", "On multi-core systems, multiple processes can be Running simultaneously (one per core). The OS ready queue feeds all cores."],
      commonMistakes: ["Confusing Ready with Running — Ready means waiting for the CPU; Running means actually executing on a CPU core.", "Thinking a Blocked process is wasting CPU — it's not. It gave up the CPU, and another process is running. The OS moves it back to Ready when I/O completes."],
      relatedTopics: ["Processes & Process Control Block", "Context Switching", "CPU Scheduling & Scheduler"],
      externalLinks: [{ label: "Process States (Wiki)", url: "https://en.wikipedia.org/wiki/Process_state" }],
      mcqs: [{ question: "What causes a process to transition from Running to Blocked?", options: ["Time slice expires", "I/O request or waiting for an event", "Process finishes", "Higher priority process arrives"], answer: 1, explanations: ["Time slice expiry causes Running -> Ready (preemption).", "Correct — a Running process transitions to Blocked when it requests I/O (read, write) or waits for an event (lock, signal). It gives up the CPU until the I/O completes or the event occurs, then moves to Ready.", "Finishing causes Running -> Terminated.", "Higher priority arrival causes Running -> Ready (preemption)."], difficulty: "medium" }] },
    { id: "context-switching", title: "Context Switching", difficulty: "medium", definition: "A context switch is the process of saving the currently running process's state (registers, PC, memory map) into its PCB and loading the next process's state from its PCB. It is pure overhead — no useful work happens during a switch. Frequent context switches degrade performance. The scheduler decides when and to whom to switch.",
      coreUnderstanding: "A context switch is the OS saving one process's state and loading another's. The current process's registers, program counter, and memory management info are saved into its PCB. The next process's state is loaded from its PCB. This is pure overhead — no useful computation happens during the switch. Context switches take ~1-10 microseconds, and the cache is cold after a switch (cache miss penalty). Frequent context switching (too-small time slices in Round Robin) degrades performance because the CPU spends more time switching than computing.",
      howItWorks: "1. Trigger: timer interrupt (time slice expired), I/O request (process blocks), or higher-priority process arrives.\n2. Save: the OS saves the current process's CPU registers (including PC, stack pointer) into its PCB.\n3. Schedule: the scheduler picks the next process from the ready queue.\n4. Load: the OS loads the next process's PCB (registers, PC, memory map) into the CPU.\n5. Address space switch: if the new process has a different address space, the page table base register is updated (TLB flush — expensive).\n6. Resume: the CPU continues executing the new process from where it left off (the saved PC).\n7. Cost: ~1-10 microseconds for the switch itself, plus cache cold-start penalty (TLB and CPU cache misses).\n8. Thread switch: cheaper than process switch (same address space, no TLB flush).",
      codeExamples: [{ lang: "text", code: "Context Switch Steps:\n\n1. Timer interrupt fires (time slice expired)\n   |\n2. CPU switches to kernel mode (interrupt handler)\n   |\n3. Save Process A's state to its PCB:\n   - General registers (R0-R15)\n   - Program Counter (PC)\n   - Stack Pointer (SP)\n   - Memory management registers (page table base)\n   |\n4. Scheduler picks Process B from ready queue\n   |\n5. Load Process B's state from its PCB:\n   - Restore registers\n   - Restore PC (resume where B left off)\n   - Update page table base (TLB flush!)\n   |\n6. CPU resumes Process B\n\nCost: ~1-10 microseconds + cache cold-start\n\n// Thread context switch is cheaper:\n// Same address space -> no TLB flush\n// Only save/restore registers (shared memory stays)", output: "(context switch steps)", note: "Context switch: save current process's state (registers, PC, memory map) to PCB, load next process's state. Pure overhead (~1-10 microseconds + cache penalty). Thread switches are cheaper (no TLB flush)." }],
      marginNotes: ["Context switches are pure overhead — no useful work happens during a switch. The CPU saves/restores registers, updates the page table base (TLB flush), and the cache is cold. Too-frequent switching degrades performance.", "Thread context switches are cheaper than process switches because threads share the same address space — no TLB flush needed, only register save/restore.", "The TLB (Translation Lookaside Buffer) caches virtual-to-physical address translations. Switching address spaces (process switch) flushes the TLB — the new process starts with a cold TLB, causing page table walk overhead."],
      commonMistakes: ["Thinking context switching is free — it's not. Each switch costs ~1-10 microseconds plus cache cold-start penalty. Too-small time slices (Round Robin with quantum=1ms) cause excessive switching.", "Confusing context switch with mode switch — a mode switch (user to kernel via syscall) is cheaper than a context switch (switching to a different process)."],
      relatedTopics: ["Process States & Transitions", "Processes & Process Control Block", "CPU Scheduling & Scheduler"],
      externalLinks: [{ label: "Context Switch (Wiki)", url: "https://en.wikipedia.org/wiki/Context_switch" }],
      mcqs: [{ question: "Why is a context switch considered pure overhead?", options: ["It uses too much memory", "No useful computation happens during a switch — the CPU only saves/restores state", "It requires network access", "It is a user operation"], answer: 1, explanations: ["Memory is not the main issue.", "Correct — during a context switch, the CPU saves the current process's state (registers, PC) into its PCB and loads the next process's state. No useful computation happens — it's pure overhead. Frequent switches degrade performance because the CPU spends time switching instead of computing.", "No network involved.", "It's an OS operation, not user-initiated."], difficulty: "medium" }] },
    { id: "process-scheduling", title: "CPU Scheduling & Scheduler", difficulty: "medium", definition: "The CPU scheduler decides which ready process runs next when the CPU becomes free. The goal is to maximize CPU utilization and throughput while minimizing wait time and response time. Scheduling can be preemptive (the OS can force a running process off the CPU) or non-preemptive (a process runs until it blocks or finishes).",
      coreUnderstanding: "The CPU scheduler is the OS component that decides which ready process gets the CPU next. Goals: maximize CPU utilization (keep the CPU busy), throughput (jobs per unit time), and fairness; minimize wait time, response time, and turnaround time. Two types: preemptive (the OS can interrupt a running process — timer interrupt, higher priority arrival) and non-preemptive (a process runs until it blocks or finishes — no interruption). Modern OSes use preemptive scheduling for responsiveness. Common algorithms: FCFS (simple, fair but convoy effect), SJF (optimal wait time but needs future knowledge), Round Robin (fair, responsive), Priority (starvation risk), Multilevel Feedback (adaptive).",
      howItWorks: "1. Scheduling decisions occur at: process creation (new process), process termination (CPU free), process blocks (I/O request), I/O completion (process becomes ready), timer interrupt (time slice expired).\n2. Preemptive: the OS can force a running process off the CPU (timer interrupt, higher priority arrival). Modern OSes use this.\n3. Non-preemptive: a process runs until it blocks or finishes. Simpler but less responsive.\n4. Metrics: CPU utilization (% busy), throughput (jobs/time), turnaround time (submission to completion), waiting time (time in ready queue), response time (first response).\n5. Algorithms: FCFS (first come first served), SJF (shortest job first), Round Robin (time slices), Priority, Multilevel Feedback Queues.\n6. The scheduler maintains a ready queue (list of ready processes) and picks the next one according to the algorithm.",
      codeExamples: [{ lang: "text", code: "Scheduling Metrics:\n  CPU Utilization: % of time CPU is busy (goal: ~100%)\n  Throughput:      number of processes completed per time unit\n  Turnaround Time: submission -> completion (total time in system)\n  Waiting Time:   time spent in ready queue\n  Response Time:   submission -> first response\n\nPreemptive vs Non-preemptive:\n  Preemptive:     OS can interrupt running process (timer, priority)\n  Non-preemptive: process runs until blocks or finishes\n\nScheduling Algorithms:\n  FCFS:           First Come First Served (simple, convoy effect)\n  SJF:            Shortest Job First (optimal wait, needs future)\n  Round Robin:    Time slices, circular (fair, responsive)\n  Priority:       Highest priority first (starvation risk)\n  MLFQ:           Multilevel Feedback (adaptive)\n\nReady Queue Example:\n  Time 0: [P1(10), P2(5), P3(3)]\n  FCFS:   P1 runs 10, P2 runs 5, P3 runs 3\n  SJF:    P3 runs 3, P2 runs 5, P1 runs 10\n  RR(q=4): P1 runs 4, P2 runs 4, P3 runs 3, P2 runs 1, P1 runs 6", output: "(scheduling overview)", note: "The scheduler picks which ready process runs next. Preemptive (can interrupt) vs non-preemptive (runs until done). Goals: maximize utilization/throughput, minimize wait/response. Algorithms: FCFS, SJF, RR, Priority, MLFQ." }],
      marginNotes: ["Preemptive scheduling (modern OSes) lets the OS interrupt a running process (timer interrupt, higher priority). Non-preemptive lets a process run until it blocks or finishes. Preemptive is more responsive but has context switch overhead.", "Key metrics: CPU utilization (% busy), throughput (jobs/time), turnaround time (total time in system), waiting time (time in ready queue), response time (first response). Different algorithms optimize different metrics.", "There's no perfect scheduling algorithm — each has trade-offs. FCFS is simple but unfair (convoy effect). SJF is optimal for wait time but needs future knowledge. RR is fair but has context switch overhead. Priority can starve low-priority processes (fix with aging)."],
      commonMistakes: ["Thinking one scheduling algorithm is always best — each has trade-offs. FCFS is simple but suffers from the convoy effect. SJF is optimal but can't predict burst times. RR is fair but has overhead. Priority risks starvation.", "Confusing turnaround time with waiting time — turnaround = waiting + execution time. Waiting = time spent in the ready queue only."],
      relatedTopics: ["FCFS Scheduling", "SJF & SRTF Scheduling", "Round Robin Scheduling"],
      externalLinks: [{ label: "CPU Scheduling (Wiki)", url: "https://en.wikipedia.org/wiki/Scheduling_(computing)" }],
      mcqs: [{ question: "What is the difference between preemptive and non-preemptive scheduling?", options: ["Preemptive is faster", "Preemptive: the OS can interrupt a running process (timer, priority); non-preemptive: a process runs until it blocks or finishes", "Preemptive uses more memory", "They are the same"], answer: 1, explanations: ["Speed is not the key difference.", "Correct — preemptive scheduling lets the OS force a running process off the CPU (timer interrupt, higher priority arrival). Non-preemptive scheduling lets a process run until it voluntarily blocks or finishes. Modern OSes use preemptive scheduling for responsiveness.", "Memory is unrelated.", "They are fundamentally different."], difficulty: "medium" }] },
    { id: "fcfs-scheduling", title: "FCFS Scheduling", difficulty: "easy", definition: "First-Come First-Served is the simplest scheduling algorithm — processes run in the order they arrive, non-preemptively. It's fair but suffers from the convoy effect: a long process holds the CPU while short processes wait behind it, increasing average wait time dramatically.",
      coreUnderstanding: "FCFS is the simplest scheduling algorithm: processes run in arrival order, non-preemptively (a process runs until it finishes or blocks). It's fair (no starvation) but suffers from the convoy effect: if a long CPU-bound process arrives first, all short processes wait behind it, dramatically increasing average wait time. FCFS is like a single-line queue at a bank — the first person in line gets served first, regardless of how long their transaction takes. It's rarely used alone in modern OSes but is a building block for more complex algorithms.",
      howItWorks: "1. Maintain a FIFO (first-in, first-out) ready queue.\n2. When the CPU is free, dispatch the process at the front of the queue.\n3. The process runs until it finishes or blocks (non-preemptive).\n4. When it finishes/blocks, dispatch the next process from the queue.\n5. Convoy effect: if P1 (long burst) arrives first, P2 and P3 (short bursts) wait for P1 to finish, even though they could have completed quickly.",
      codeExamples: [{ lang: "text", code: "FCFS Example:\n\nProcesses (burst time):\n  P1: 10ms  (arrives at 0)\n  P2:  5ms  (arrives at 1)\n  P3:  3ms  (arrives at 2)\n\nFCFS Schedule (arrival order):\n  Time 0-10:  P1 runs (10ms)\n  Time 10-15: P2 runs (5ms)\n  Time 15-18: P3 runs (3ms)\n\nWait times:\n  P1: 0ms (starts immediately)\n  P2: 9ms (waits from 1 to 10)\n  P3: 13ms (waits from 2 to 15)\n  Average wait: (0+9+13)/3 = 7.3ms\n\nCompare with SJF (P3 first):\n  P3: 0ms, P2: 2ms, P1: 7ms\n  Average wait: (0+2+7)/3 = 3.0ms\n\n// Convoy effect: P1 blocks P2 and P3\n// even though they're much shorter.", output: "(FCFS schedule)", note: "FCFS: processes run in arrival order, non-preemptively. Fair but suffers from the convoy effect — a long process holds the CPU while short processes wait." }],
      marginNotes: ["The convoy effect: a long CPU-bound process holds the CPU while many short I/O-bound processes wait behind it. This dramatically increases average wait time — the opposite of what you want.", "FCFS is non-preemptive: a process runs until it finishes or blocks. The OS can't interrupt it. This means a runaway process can hog the CPU indefinitely.", "FCFS is rarely used alone in modern OSes, but it's a building block. Multilevel feedback queues often use FCFS for the lowest-priority (background) queue."],
      commonMistakes: ["Thinking FCFS is always fair — it's fair in order (no starvation) but unfair in wait time (convoy effect: short processes wait behind long ones).", "Confusing non-preemptive with preemptive FCFS — standard FCFS is non-preemptive. A preemptive version doesn't really make sense (what would preempt?)."],
      relatedTopics: ["SJF & SRTF Scheduling", "Round Robin Scheduling", "CPU Scheduling & Scheduler"],
      externalLinks: [{ label: "FCFS (Wiki)", url: "https://en.wikipedia.org/wiki/Scheduling_(computing)#First-come,_first-served" }],
      mcqs: [{ question: "What is the convoy effect in FCFS?", options: ["Processes arrive in groups", "A long process holds the CPU while short processes wait behind it, increasing average wait time", "The CPU crashes", "Processes are served randomly"], answer: 1, explanations: ["It's not about grouping.", "Correct — the convoy effect: a long CPU-bound process holds the CPU while many short processes wait behind it in the ready queue. This dramatically increases average wait time, the opposite of what you want.", "No crash — just poor performance.", "FCFS serves in order, not randomly."], difficulty: "medium" }] },
    { id: "sjf-scheduling", title: "SJF & SRTF Scheduling", difficulty: "medium", definition: "Shortest Job First runs the process with the shortest burst time first, minimizing average waiting time (provably optimal for non-preemptive). SRTF (Shortest Remaining Time First) is the preemptive version. The problem: you must know or estimate burst times in advance, which is usually impossible in practice.",
      coreUnderstanding: "SJF runs the shortest job first, which provably minimizes average waiting time. SRTF (Shortest Remaining Time First) is the preemptive version: if a new process arrives with a shorter burst than the remaining time of the currently running process, the running process is preempted. SJF is theoretically optimal but impractical — you can't know future burst times. In practice, the OS estimates burst time from past behavior (exponential averaging). SJF also risks starvation: long processes may never run if short processes keep arriving.",
      howItWorks: "1. SJF (non-preemptive): when the CPU is free, pick the ready process with the shortest burst time. Run it to completion.\n2. SRTF (preemptive): when a new process arrives, compare its burst to the remaining time of the running process. If the new one is shorter, preempt.\n3. Optimal: SJF provably minimizes average waiting time (proof by exchange argument).\n4. The catch: you need to KNOW burst times. In practice, estimate: predicted_next = alpha * actual_last + (1-alpha) * predicted_last.\n5. Starvation: long processes can starve if short processes keep arriving. Aging (increasing priority over time) is the fix.\n6. SRTF has more context switches than SJF (preemption), but lower average wait time.",
      codeExamples: [{ lang: "text", code: "SJF vs SRTF Example:\n\nProcesses (burst time, arrival):\n  P1: 7ms (arrives at 0)\n  P2: 4ms (arrives at 2)\n  P3: 1ms (arrives at 4)\n  P4: 4ms (arrives at 5)\n\nSJF (non-preemptive):\n  0-7:  P1 (only process at time 0)\n  7-8:  P3 (shortest of P2=4, P3=1, P4=4)\n  8-12: P2 (P2 and P4 both 4, pick P2)\n  12-16: P4\n  Avg wait: (0+5+3+7)/4 = 3.75ms\n\nSRTF (preemptive):\n  0-2:  P1 (runs 2ms, 5ms remaining)\n  2-4:  P2 arrives (4ms), P1 has 5ms left -> P2 runs\n  4:    P3 arrives (1ms), P2 has 2ms left -> P3 preempts\n  4-5:  P3 runs (1ms)\n  5:    P4 arrives (4ms), P2 has 2ms, P4 has 4ms -> P2\n  5-6:  P2 finishes (1ms remaining)\n  6-11: P1 (5ms remaining) -> P1 runs\n  Actually: P1 has 5ms, P4 has 4ms -> P4 first\n  6-10: P4\n  10-15: P1\n  Avg wait: much lower", output: "(SJF/SRTF schedule)", note: "SJF: shortest job first (optimal wait time, but needs future knowledge). SRTF: preemptive version (shortest remaining time). Risk: starvation of long processes. Practice: estimate burst times from history." }],
      marginNotes: ["SJF is provably optimal for average wait time (exchange argument: swapping a shorter job before a longer one always reduces total wait). But it needs to KNOW burst times, which is impossible in practice.", "SRTF (preemptive SJF) preempts the running process if a new one arrives with a shorter burst. This further reduces wait time but increases context switches.", "Starvation: in SJF/SRTF, long processes can starve if short processes keep arriving. The fix is aging — gradually increase priority over time so even long processes eventually run."],
      commonMistakes: ["Thinking SJF is practical — you can't know future burst times. In practice, the OS estimates from past behavior (exponential averaging).", "Forgetting starvation: SJF can starve long processes if short ones keep arriving. Always consider aging or time-slicing to prevent this."],
      relatedTopics: ["FCFS Scheduling", "Round Robin Scheduling", "Priority Scheduling"],
      externalLinks: [{ label: "SJF (Wiki)", url: "https://en.wikipedia.org/wiki/Shortest_job_next" }],
      mcqs: [{ question: "Why is SJF impractical in real systems?", options: ["It's too slow", "You can't know future burst times in advance", "It requires too much memory", "It's not fair"], answer: 1, explanations: ["Speed is not the issue.", "Correct — SJF requires knowing each process's burst time (CPU time needed) in advance. In practice, you can't predict this. The OS estimates from past behavior (exponential averaging), but estimates can be wrong.", "Memory is not the constraint.", "Fairness is a concern (starvation), but the main issue is unpredictability."], difficulty: "medium" }] },
    { id: "round-robin", title: "Round Robin Scheduling", difficulty: "medium", definition: "Round Robin gives each process a fixed time quantum (e.g., 10ms) in circular order. When the quantum expires, the process is preempted and goes to the back of the ready queue. RR is fair and responsive — no process waits too long. The quantum size is critical: too small causes excessive context switches; too large degenerates to FCFS.",
      coreUnderstanding: "Round Robin (RR) gives each ready process a fixed time quantum (e.g., 10ms) in circular order. When the quantum expires, the process is preempted and goes to the back of the ready queue. RR is fair (no process waits too long) and responsive (good for interactive systems). The quantum size is critical: too small (1ms) causes excessive context switching overhead; too large (1000ms) degenerates to FCFS (convoy effect). The ideal quantum is typically 10-100ms — large enough to amortize context switch overhead, small enough for responsiveness.",
      howItWorks: "1. Maintain a circular ready queue.\n2. Dispatch the process at the front. Set a timer for the quantum (e.g., 10ms).\n3. If the process finishes before the quantum expires, it leaves the queue. Dispatch the next.\n4. If the quantum expires, preempt the process (timer interrupt). Move it to the back of the queue.\n5. Dispatch the next process. Repeat.\n6. Quantum size: too small -> excessive context switches (overhead). Too large -> degenerates to FCFS (convoy effect). Sweet spot: 10-100ms.\n7. RR is fair: each process gets an equal share. No starvation.\n8. RR is used in time-sharing systems (interactive) where responsiveness matters.",
      codeExamples: [{ lang: "text", code: "Round Robin Example (quantum = 4ms):\n\nProcesses (burst time):\n  P1: 10ms\n  P2: 5ms\n  P3: 3ms\n\nRR Schedule:\n  Time 0-4:  P1 runs (4ms, 6ms remaining) -> preempted\n  Time 4-8:  P2 runs (4ms, 1ms remaining) -> preempted\n  Time 8-11: P3 runs (3ms) -> DONE\n  Time 11-12: P2 runs (1ms) -> DONE\n  Time 12-16: P1 runs (4ms, 2ms remaining) -> preempted\n  Time 16-18: P1 runs (2ms) -> DONE\n\nWait times:\n  P1: 0 + 4 (P2) + 3 (P3) + 2 (P2) = 8ms waiting\n  P2: 4 (P1) + 3 (P3) = 7ms waiting\n  P3: 4 (P1) + 4 (P2) = 8ms waiting\n  Average: 7.7ms\n\n// Compare FCFS: P1=0, P2=10, P3=15, avg=8.3ms\n// RR is slightly better here, and much fairer\n// for interactive workloads.", output: "(RR schedule)", note: "RR: each process gets a time quantum (e.g., 10ms) in circular order. Fair and responsive. Quantum size is critical: too small = excessive switches, too large = degenerates to FCFS. Sweet spot: 10-100ms." }],
      marginNotes: ["The quantum size is critical: too small (1ms) causes excessive context switching (the CPU spends more time switching than computing). Too large (1000ms) degenerates to FCFS (convoy effect). Sweet spot: 10-100ms.", "RR is fair: each process gets an equal share of CPU time. No starvation. This makes it ideal for time-sharing (interactive) systems.", "RR has higher average wait time than SJF but better response time (each process gets a turn quickly). For interactive systems, response time matters more than turnaround time."],
      commonMistakes: ["Setting the quantum too small (1ms) — context switch overhead dominates. The rule of thumb: quantum should be at least 10x the context switch time.", "Thinking RR always has lower wait time than FCFS — it doesn't. RR has fairer response time, but average wait time can be higher due to the circular nature."],
      relatedTopics: ["FCFS Scheduling", "SJF & SRTF Scheduling", "Priority Scheduling"],
      externalLinks: [{ label: "Round Robin (Wiki)", url: "https://en.wikipedia.org/wiki/Round-robin_scheduling" }],
      mcqs: [{ question: "What happens if the Round Robin quantum is too small?", options: ["Processes finish faster", "Excessive context switching — the CPU spends more time switching than computing", "Starvation occurs", "The system crashes"], answer: 1, explanations: ["Small quantum doesn't make processes faster.", "Correct — if the quantum is too small (e.g., 1ms), the CPU spends most of its time context switching (saving/restoring state) instead of computing. The rule of thumb: quantum should be at least 10x the context switch time.", "RR doesn't starve (it's fair).", "No crash — just poor performance."], difficulty: "medium" }] },
    { id: "priority-scheduling", title: "Priority Scheduling", difficulty: "medium", definition: "Each process has a priority; the scheduler picks the highest-priority ready process. Priority can be static (fixed at creation) or dynamic (changes over time). The major problem is starvation — low-priority processes may never run. Aging (gradually increasing priority over time) is the standard fix.",
      coreUnderstanding: "Priority scheduling assigns each process a priority; the scheduler picks the highest-priority ready process. Priorities can be static (fixed at creation) or dynamic (change over time). The major problem: starvation — if high-priority processes keep arriving, low-priority processes may never run. The standard fix is aging: gradually increase a process's priority as it waits, so eventually even the lowest-priority process gets the CPU. Priority can be based on: user-set (nice value), system type (I/O-bound > CPU-bound), or resource needs.",
      howItWorks: "1. Each process has a priority (integer; lower number = higher priority, or vice versa depending on the system).\n2. The scheduler picks the ready process with the highest priority.\n3. If multiple have the same priority, use FCFS or RR among them.\n4. Static priority: fixed at creation. System processes > user processes. I/O-bound > CPU-bound (to keep I/O devices busy).\n5. Dynamic priority: changes over time. E.g., decrease priority after using CPU time (penalty for CPU hogs).\n6. Starvation: low-priority processes may never run if high-priority ones keep arriving.\n7. Aging fix: increase priority as wait time grows. Eventually, even the lowest-priority process gets the CPU.\n8. Preemptive vs non-preemptive: preemptive (preempt if a higher-priority process arrives), non-preemptive (run until blocks/finishes).",
      codeExamples: [{ lang: "text", code: "Priority Scheduling Example:\n\nProcesses (priority, burst):\n  P1: priority=3, burst=10ms\n  P2: priority=1, burst=5ms  (highest priority)\n  P3: priority=4, burst=3ms  (lowest priority)\n  P4: priority=2, burst=7ms\n\nSchedule (lower number = higher priority):\n  Time 0-5:   P2 (priority 1)\n  Time 5-12:  P4 (priority 2)\n  Time 12-22: P1 (priority 3)\n  Time 22-25: P3 (priority 4)\n\nWait times:\n  P1: 12ms  P2: 0ms  P3: 22ms  P4: 5ms\n\n// Starvation: if P2, P4, P1 keep arriving,\n// P3 may never run!\n\n// Aging fix:\n// After waiting 10ms, P3's priority increases\n// After 20ms, increases again\n// Eventually P3's priority exceeds others\n\n// Linux nice values: -20 (highest) to 19 (lowest)\n// Default: 0. Root can set negative.\n// $ nice -n 10 myprogram  (lower priority)\n// $ renice -5 -p 1234    (raise priority)", output: "(priority schedule)", note: "Priority scheduling: highest-priority process runs first. Static (fixed) or dynamic (changes). Problem: starvation of low-priority processes. Fix: aging (increase priority over time). Linux uses nice values." }],
      marginNotes: ["Starvation: low-priority processes may never run if high-priority ones keep arriving. The standard fix is aging — gradually increase priority as wait time grows.", "Linux uses nice values: -20 (highest priority) to 19 (lowest). Default is 0. Only root can set negative (higher) priority. Use 'nice' and 'renice' commands.", "Priority inversion: a high-priority process waits for a resource held by a low-priority process. Fix: priority inheritance — temporarily raise the low-priority process's priority to match the waiter."],
      commonMistakes: ["Forgetting about starvation — if high-priority processes keep arriving, low-priority ones never run. Always use aging to prevent this.", "Confusing priority inversion with starvation — inversion is when a high-priority process waits for a low-priority one's resource. Starvation is when a low-priority process never gets the CPU."],
      relatedTopics: ["FCFS Scheduling", "Round Robin Scheduling", "Multilevel Queue & Feedback"],
      externalLinks: [{ label: "Priority Scheduling (Wiki)", url: "https://en.wikipedia.org/wiki/Scheduling_(computing)#Fixed-priority_preemptive_scheduling" }],
      mcqs: [{ question: "What is the main problem with priority scheduling?", options: ["It's too slow", "Starvation — low-priority processes may never run if high-priority ones keep arriving", "It uses too much memory", "It's not fair to high-priority processes"], answer: 1, explanations: ["Speed is not the issue.", "Correct — if high-priority processes keep arriving, low-priority processes may never get the CPU (starvation). The standard fix is aging: gradually increase priority as wait time grows, so eventually even the lowest-priority process runs.", "Memory is unrelated.", "It's very fair to high-priority processes — that's the problem."], difficulty: "medium" }] },
    { id: "multilevel-queue", title: "Multilevel Queue & Feedback", difficulty: "hard", definition: "Multilevel queue scheduling partitions ready processes into separate queues by type (foreground interactive, background batch), each with its own scheduling algorithm. Multilevel feedback queues allow processes to move between queues based on behavior — rewarding CPU-bound processes with lower priority and giving I/O-bound processes higher priority, adapting to workload dynamically.",
      coreUnderstanding: "Multilevel Queue scheduling partitions ready processes into separate queues by type (foreground interactive, background batch), each with its own algorithm (RR for interactive, FCFS for batch). Queues have fixed priorities (foreground > background). Multilevel Feedback Queues (MLFQ) add adaptivity: processes can MOVE between queues based on behavior. A process that uses too much CPU time (CPU-bound) gets demoted to a lower-priority queue. A process that blocks for I/O quickly (I/O-bound) stays in or gets promoted to a higher-priority queue. This adapts to workload automatically and prevents starvation (via aging or periodic promotion).",
      howItWorks: "1. Multiple queues, each with a different priority level and scheduling algorithm.\n2. Fixed priority: Q0 (highest, RR, interactive), Q1 (medium, RR), Q2 (lowest, FCFS, background).\n3. The scheduler always serves the highest-priority non-empty queue first.\n4. Within a queue, use that queue's algorithm (RR, FCFS, etc.).\n5. MLFQ adds movement: a process that uses its full quantum (CPU-bound) gets demoted to a lower queue. A process that blocks before the quantum expires (I/O-bound) stays or gets promoted.\n6. This adapts: I/O-bound processes get high priority (responsive), CPU-bound processes get low priority (background, but still run when the CPU is free).\n7. Starvation prevention: periodic aging (boost all processes to the highest queue periodically).",
      codeExamples: [{ lang: "text", code: "Multilevel Feedback Queue (MLFQ) Example:\n\nQueues:\n  Q0: highest priority, RR quantum=8ms (interactive)\n  Q1: medium priority, RR quantum=16ms\n  Q2: lowest priority, FCFS (background)\n\nRules:\n  - New process enters Q0 (highest priority).\n  - If a process uses its full quantum (CPU-bound), demote to next lower queue.\n  - If a process blocks before quantum expires (I/O-bound), stay in current queue (or promote).\n  - Always serve Q0 first; only serve Q1 if Q0 is empty; only Q2 if Q1 is empty.\n\nExample:\n  P1 (CPU-bound): starts Q0, uses 8ms -> demote to Q1, uses 16ms -> demote to Q2 (FCFS).\n  P2 (I/O-bound): starts Q0, blocks after 2ms (I/O) -> stays in Q0 (responsive).\n\n// Result: I/O-bound (interactive) processes stay in Q0 (responsive).\n// CPU-bound processes sink to Q2 (background) but still run.\n// Periodic boost: every 1s, move all processes to Q0 (prevents starvation).\n\n// This is what real OS schedulers (Linux CFS, Windows) approximate.", output: "(MLFQ example)", note: "MLFQ: multiple queues with different priorities. Processes that use too much CPU get demoted (lower priority); I/O-bound processes stay high (responsive). Periodic boost prevents starvation. Used by real OS schedulers." }],
      marginNotes: ["MLFQ adapts to workload: I/O-bound processes (block quickly) stay in high-priority queues (responsive). CPU-bound processes (use full quantum) get demoted to low-priority queues (background). This gives interactive responsiveness without sacrificing throughput.", "Starvation prevention: periodic boost — every S ms, move all processes to the highest-priority queue. This ensures even the lowest-priority (CPU-bound) processes eventually get the CPU.", "Real OS schedulers (Linux CFS, Windows scheduler) approximate MLFQ ideas: they track CPU time per process and adjust priorities dynamically to balance responsiveness and fairness."],
      commonMistakes: ["Thinking multilevel queues and MLFQ are the same — multilevel queues are STATIC (processes stay in their assigned queue). MLFQ adds FEEDBACK: processes move between queues based on behavior.", "Forgetting starvation prevention — low-priority queues can starve if high-priority ones keep arriving. Use periodic boost (aging) to prevent this."],
      relatedTopics: ["Priority Scheduling", "Round Robin Scheduling", "CPU Scheduling & Scheduler"],
      externalLinks: [{ label: "MLFQ (Wiki)", url: "https://en.wikipedia.org/wiki/Multilevel_feedback_queue" }],
      mcqs: [{ question: "What is the key difference between Multilevel Queue and Multilevel Feedback Queue (MLFQ)?", options: ["MLFQ has more queues", "MLFQ allows processes to move between queues based on behavior; Multilevel Queue is static", "MLFQ is faster", "They are the same"], answer: 1, explanations: ["Queue count is not the key difference.", "Correct — Multilevel Queue assigns processes to fixed queues (static). MLFQ adds feedback: processes MOVE between queues based on behavior. CPU-bound processes get demoted; I/O-bound processes stay high. This adapts to workload dynamically.", "Speed is not the key difference.", "They are different — MLFQ adds movement."], difficulty: "hard" }] },
    { id: "threads", title: "Threads & Multithreading", difficulty: "medium", definition: "A thread is the smallest unit of execution within a process. A process can have multiple threads sharing the same memory space (code, data, heap) but each having its own stack and registers. Threads are lighter than processes (cheaper to create and switch). User-level threads are managed by a library; kernel-level threads are managed by the OS. Modern OSs use 1:1 (one user thread per kernel thread) mapping.",
      coreUnderstanding: "A thread is the smallest unit of execution within a process. Multiple threads in the same process share memory (code, data, heap, open files) but each has its own stack, registers, and program counter. Threads are lighter weight than processes: creation is cheaper (no memory copy), context switching is faster (same address space, no TLB flush). Threading models: (1) User-level threads (managed by a library, OS doesn't see them — fast but can't use multiple cores). (2) Kernel-level threads (managed by the OS — can use multiple cores). (3) 1:1 mapping (one user thread per kernel thread — modern standard, used by Linux/Windows).",
      howItWorks: "1. Thread components: thread ID, program counter, registers, stack. Shared with other threads: code segment, data segment, heap, open files, signals.\n2. Benefits: concurrency (multiple threads running simultaneously on multi-core), responsiveness (one thread blocks, others continue), resource sharing (shared memory), economy (cheaper than processes).\n3. User-level threads: managed by a thread library (pthreads in user space). Fast (no syscall for create/switch). But if one thread blocks, ALL block (the OS sees one process). Can't use multiple cores.\n4. Kernel-level threads: managed by the OS. Can use multiple cores. If one blocks, others continue. Slower (syscalls for create/switch).\n5. 1:1 model: each user thread maps to one kernel thread. Used by Linux (clone) and Windows. Best of both: multi-core support and blocking independence.\n6. N:1 model: many user threads on one kernel thread. Can't use multiple cores.\n7. M:N model: M user threads on N kernel threads. Complex, used by Go (goroutines) and Erlang.",
      codeExamples: [{ lang: "c", code: "#include <pthread.h>\n#include <stdio.h>\n\nvoid* worker(void* arg) {\n    int id = *(int*)arg;\n    printf(\"Thread %d running\\n\", id);\n    return NULL;\n}\n\nint main() {\n    pthread_t t1, t2;\n    int id1 = 1, id2 = 2;\n    \n    // Create threads (cheaper than fork)\n    pthread_create(&t1, NULL, worker, &id1);\n    pthread_create(&t2, NULL, worker, &id2);\n    \n    // Wait for threads to finish\n    pthread_join(t1, NULL);\n    pthread_join(t2, NULL);\n    \n    printf(\"All threads done\\n\");\n    return 0;\n}\n\n// Thread shares with other threads:\n//   - Code segment (functions)\n//   - Data segment (global variables)\n//   - Heap (malloc'd memory)\n//   - Open files\n//\n// Thread has its own:\n//   - Stack (local variables)\n//   - Registers (PC, SP)\n//   - Thread ID", output: "Thread 1 running\nThread 2 running\nAll threads done", note: "A thread is the smallest unit of execution within a process. Threads share memory (code, data, heap, files) but have separate stacks and registers. Cheaper than processes. Modern OSes use 1:1 (one user thread per kernel thread)." }],
      marginNotes: ["Threads share memory (code, data, heap, open files) but have separate stacks, registers, and program counters. This makes communication fast (shared memory) but requires synchronization (race conditions).", "Thread creation is much cheaper than process creation (fork copies the address space; thread creation just allocates a stack). Thread context switches are faster too (no TLB flush).", "1:1 threading model (Linux, Windows): each user thread maps to one kernel thread. This allows multi-core parallelism and independent blocking. Go's goroutines use M:N (many user threads on fewer kernel threads) for even lighter-weight concurrency."],
      commonMistakes: ["Thinking threads are always safer than processes — they share memory, so race conditions and data corruption are risks. Processes are isolated; threads are not.", "Confusing user-level and kernel-level threads — user-level threads (library-managed) can't use multiple cores and block entirely if one thread does blocking I/O. Kernel-level threads (OS-managed) don't have these limitations."],
      relatedTopics: ["Process vs Thread", "Race Conditions & Critical Sections", "Mutex Locks"],
      externalLinks: [{ label: "Threads (Wiki)", url: "https://en.wikipedia.org/wiki/Thread_(computing)" }],
      mcqs: [{ question: "What do threads within the same process share?", options: ["Nothing — each thread is isolated", "Memory (code, data, heap, open files) — but each has its own stack and registers", "Only the stack", "Only the heap"], answer: 1, explanations: ["Threads are not isolated — they share memory.", "Correct — threads in the same process share the code segment, data segment, heap, and open files. Each thread has its own stack (local variables), registers, and program counter. This makes communication fast (shared memory) but requires synchronization.", "The stack is private to each thread.", "The heap is shared, but so is code, data, and files."], difficulty: "medium" }] },
    { id: "process-vs-thread", title: "Process vs Thread", difficulty: "easy", definition: "Processes have separate memory spaces (isolated, safe, but IPC is expensive). Threads share memory within a process (fast communication, but race conditions require synchronization). Creating a process is expensive (fork copies memory); creating a thread is cheap. Use processes for isolation and security; threads for performance and shared state.",
      coreUnderstanding: "Process vs Thread: processes have separate address spaces (isolated, safe, but communication requires IPC which is expensive). Threads share an address space within a process (fast communication via shared memory, but race conditions require synchronization). Process creation is expensive (fork copies the address space, though copy-on-write helps). Thread creation is cheap (just allocate a stack). Context switching between threads is faster than between processes (no TLB flush, same address space). Use processes for isolation and security (browser tabs, microservices); use threads for performance and shared state (web servers, parallel computation).",
      howItWorks: "1. Process: separate address space. Can't access another process's memory directly. Communication via IPC (pipes, sockets, shared memory). Isolated — a crash in one process doesn't crash others.\n2. Thread: shares address space with other threads in the same process. Communication via shared variables (fast). Not isolated — a crash (segfault) in one thread crashes the entire process.\n3. Creation cost: fork() copies the address space (expensive, though COW helps). pthread_create() allocates a stack (cheap).\n4. Context switch: process switch requires TLB flush (expensive). Thread switch doesn't (same address space).\n5. Use processes: isolation needed (browser tabs, server processes, security-sensitive code).\n6. Use threads: shared state needed (web server handling many connections, parallel computation, GUI responsiveness).\n7. Hybrid: multi-process + multi-threaded (e.g., Chrome: each tab is a process, each process has multiple threads).",
      codeExamples: [{ lang: "text", code: "Process vs Thread Comparison:\n\n                    Process              Thread\n─────────────────────────────────────────────────────\nMemory             Separate             Shared (same process)\nCommunication      IPC (pipes, sockets)  Shared variables\nIsolation          High (safe)          Low (shared)\nCreation cost      High (fork copies)   Low (allocate stack)\nContext switch     Slow (TLB flush)     Fast (same space)\nCrash impact       Only that process    Entire process\n\nWhen to use processes:\n  - Browser tabs (isolation: one tab crash doesn't kill all)\n  - Server processes (isolation: one crash doesn't kill the server)\n  - Security-sensitive code (isolation prevents data leaks)\n\nWhen to use threads:\n  - Web server (shared cache, fast request handling)\n  - Parallel computation (shared data, fast communication)\n  - GUI (background work while UI stays responsive)\n  - I/O concurrency (one thread blocks, others continue)\n\n// Chrome: hybrid (multi-process + multi-threaded)\n// Each tab is a process (isolation), each process\n// has multiple threads (render, network, etc.)", output: "(comparison table)", note: "Processes: isolated, safe, IPC is expensive. Threads: shared memory, fast communication, needs synchronization. Processes for isolation/security; threads for performance/shared state." }],
      marginNotes: ["Use processes for isolation and security (browser tabs, server processes). A crash in one process doesn't affect others. Use threads for performance and shared state (web servers, parallel computation). Threads share memory, making communication fast.", "Context switching between threads is faster than between processes because threads share the same address space — no TLB flush. This is a key performance advantage of threads.", "Chrome's model: each tab is a separate process (isolation — one crash doesn't kill the browser), and each process has multiple threads (render, network, JS). This hybrid approach gives both isolation and performance."],
      commonMistakes: ["Using processes when threads would be better (or vice versa). Processes for isolation/security; threads for performance/shared state. The choice depends on whether isolation or performance matters more.", "Thinking thread crashes are isolated — they're not. A segfault in one thread crashes the entire process (all threads). Process crashes are isolated to that process."],
      relatedTopics: ["Threads & Multithreading", "Inter-Process Communication (IPC)", "Race Conditions & Critical Sections"],
      externalLinks: [{ label: "Process vs Thread", url: "https://en.wikipedia.org/wiki/Process_(computing)#Process_vs._thread" }],
      mcqs: [{ question: "Why is thread context switching faster than process context switching?", options: ["Threads are smaller", "Threads share the same address space — no TLB flush needed", "Threads use less CPU", "Threads are simpler"], answer: 1, explanations: ["Size is not the key reason.", "Correct — threads in the same process share the same address space. Switching between threads doesn't require updating the page table base or flushing the TLB (Translation Lookaside Buffer). Process switches require a TLB flush, which is expensive (the new process starts with a cold TLB).", "CPU usage is similar.", "Simplicity is not the key reason."], difficulty: "medium" }] },
    { id: "inter-process-communication", title: "Inter-Process Communication (IPC)", difficulty: "medium", definition: "IPC mechanisms let processes communicate and synchronize. Methods: pipes (unidirectional byte streams), named pipes/FIFOs (persistent pipes), message queues (structured messages), shared memory (fastest — processes map the same memory region), semaphores (synchronization), sockets (network-capable), and signals (async notifications). Shared memory is fastest but requires explicit synchronization.",
      coreUnderstanding: "IPC (Inter-Process Communication) mechanisms let processes communicate and synchronize. Since processes have separate address spaces, they can't share variables directly. IPC methods: (1) Pipes — unidirectional byte streams between parent and child. (2) Named pipes/FIFOs — persistent pipes accessible by any process. (3) Message queues — structured messages (not just bytes). (4) Shared memory — fastest IPC: processes map the same physical memory region into their address spaces. (5) Semaphores — synchronization (not data transfer). (6) Sockets — network-capable, bidirectional. (7) Signals — async notifications (SIGINT, SIGKILL). Shared memory is fastest but requires explicit synchronization (semaphores/mutexes) to prevent race conditions.",
      howItWorks: "1. Pipes: pipe(fd) creates two file descriptors — fd[0] for reading, fd[1] for writing. Unidirectional. Usually used between parent and child (fork inherits the pipe). Data is a byte stream.\n2. Named pipes (FIFOs): mkfifo(name) creates a named pipe in the file system. Any process can open it. Persists beyond the creating process.\n3. Message queues: msgget/msgsnd/msgrcv. Structured messages (type + data). Asynchronous — sender doesn't wait for receiver.\n4. Shared memory: shmget/shmat. Fastest IPC — processes map the same physical memory. No data copying. Requires synchronization (semaphores).\n5. Semaphores: semget/semop. Counting synchronization. Used with shared memory to coordinate access.\n6. Sockets: socket/bind/connect/send/recv. Bidirectional, network-capable. Can connect processes on different machines.\n7. Signals: kill(pid, SIGTERM). Async — interrupts the receiver. Used for simple notifications (Ctrl+C = SIGINT).",
      codeExamples: [{ lang: "c", code: "// Pipe example: parent writes, child reads\n#include <unistd.h>\n#include <stdio.h>\n\nint main() {\n    int fd[2];\n    pipe(fd);  // fd[0]=read, fd[1]=write\n    \n    if (fork() == 0) {  // Child\n        close(fd[1]);  // close write end\n        char buf[100];\n        read(fd[0], buf, 100);  // read from pipe\n        printf(\"Child got: %s\\n\", buf);\n    } else {  // Parent\n        close(fd[0]);  // close read end\n        write(fd[1], \"Hello from parent!\", 18);\n        wait(NULL);\n    }\n    return 0;\n}\n\n// Shared memory example (fastest IPC):\n// int shmid = shmget(key, size, IPC_CREAT|0666);\n// char *addr = shmat(shmid, NULL, 0);\n// // Both processes can read/write addr\n// // Need a semaphore to synchronize!\n\n// Socket example (network-capable):\n// int sock = socket(AF_INET, SOCK_STREAM, 0);\n// connect(sock, &addr, sizeof(addr));\n// send(sock, data, len, 0);\n\n// Signal example (async notification):\n// kill(pid, SIGTERM);  // send signal to process", output: "Child got: Hello from parent!", note: "IPC methods: pipes (byte stream), named pipes (persistent), message queues (structured), shared memory (fastest, needs sync), sockets (network), signals (async). Shared memory is fastest but requires semaphores for synchronization." }],
      marginNotes: ["Shared memory is the FASTEST IPC (no data copying — processes map the same physical memory). But it requires explicit synchronization (semaphores/mutexes) to prevent race conditions.", "Sockets are the most versatile IPC: bidirectional, network-capable (can connect processes on different machines), and work across language boundaries. Most network programming uses sockets.", "Pipes are unidirectional and usually between parent-child (fork inherits the pipe). For bidirectional communication, use two pipes or a socket."],
      commonMistakes: ["Using shared memory without synchronization — race conditions corrupt data. Always use a semaphore or mutex to coordinate access.", "Forgetting to close unused pipe ends — if the parent doesn't close the read end and the child doesn't close the write end, the pipe never signals EOF (read blocks forever)."],
      relatedTopics: ["Process vs Thread", "Race Conditions & Critical Sections", "Semaphores"],
      externalLinks: [{ label: "IPC (Wiki)", url: "https://en.wikipedia.org/wiki/Inter-process_communication" }],
      mcqs: [{ question: "Which IPC mechanism is the fastest for data transfer?", options: ["Pipes", "Sockets", "Shared memory — no data copying, processes map the same memory", "Message queues"], answer: 2, explanations: ["Pipes copy data through a kernel buffer.", "Sockets also copy data through a kernel buffer.", "Correct — shared memory is the fastest IPC. Both processes map the same physical memory region into their address spaces. No data is copied — writes by one process are immediately visible to the other. The trade-off: requires explicit synchronization (semaphores).", "Message queues copy data."], difficulty: "medium" }] },
    { id: "race-conditions", title: "Race Conditions & Critical Sections", difficulty: "medium", definition: "A race condition occurs when multiple threads/processes access shared data concurrently and the outcome depends on the timing of execution. The section of code accessing shared data is the critical section. To prevent races, the critical section must be protected so that only one thread enters at a time — mutual exclusion. The requirements: mutual exclusion, progress, bounded waiting.",
      coreUnderstanding: "A race condition occurs when multiple threads access shared data concurrently, and the result depends on the timing of their execution. The code section that accesses shared data is the critical section. To prevent races, the critical section must be protected so that only one thread enters at a time — mutual exclusion. The three requirements for a correct solution: (1) Mutual exclusion — only one thread in the critical section at a time. (2) Progress — if no thread is in the critical section, a waiting thread should be able to enter (no deadlock). (3) Bounded waiting — a waiting thread should eventually enter (no starvation).",
      howItWorks: "1. Race condition example: count++ (read count, add 1, write count). If two threads do this simultaneously, one increment can be lost.\n2. Thread A reads count=5. Thread B reads count=5. Both write count=6. One increment is lost.\n3. The critical section is the code that accesses shared data: { temp = count; temp++; count = temp; }.\n4. Mutual exclusion: only one thread in the critical section at a time. Others wait.\n5. Progress: if no thread is in the critical section, a waiting thread should be chosen to enter (no deadlock).\n6. Bounded waiting: a waiting thread should eventually enter (no starvation).\n7. Solutions: mutex locks, semaphores, monitors, atomic operations.\n8. The challenge: software-only solutions (Peterson's algorithm) are complex and not used in practice. Hardware support (atomic test-and-set, compare-and-swap) makes it practical.",
      codeExamples: [{ lang: "c", code: "// RACE CONDITION: count++ is not atomic\nint count = 0;\n\n// Thread A and Thread B both do this:\nvoid increment() {\n    count++;  // RACE CONDITION!\n    // This is actually: read count, add 1, write count\n    // If A and B both read 5, both write 6 -> one lost!\n}\n\n// After 10000 increments from each thread:\n// Expected: 20000\n// Actual: ~16500 (lost increments!)\n\n// FIX 1: Mutex lock\npthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;\nvoid safe_increment() {\n    pthread_mutex_lock(&lock);\n    count++;  // protected critical section\n    pthread_mutex_unlock(&lock);\n}\n\n// FIX 2: Atomic operation\n#include <stdatomic.h>\natomic_int count = 0;\nvoid atomic_increment() {\n    atomic_fetch_add(&count, 1);  // atomic, no race\n}\n\n// Critical Section Requirements:\n// 1. Mutual exclusion: only one thread inside\n// 2. Progress: if empty, someone gets in (no deadlock)\n// 3. Bounded waiting: no starvation (eventually enters)", output: "(race condition)", note: "A race condition: multiple threads access shared data concurrently, outcome depends on timing. The critical section accesses shared data. Fix: mutual exclusion (mutex, semaphore, atomic). Requirements: mutual exclusion, progress, bounded waiting." }],
      marginNotes: ["count++ is NOT atomic — it's read-modify-write. Two threads doing count++ concurrently can lose increments. Use a mutex or atomic operations to fix.", "The three requirements for a correct critical section solution: (1) Mutual exclusion — only one thread inside. (2) Progress — if empty, a waiting thread gets in (no deadlock). (3) Bounded waiting — no starvation (a waiting thread eventually enters).", "Race conditions are hard to debug because they're non-deterministic — they may not reproduce on every run. Always use synchronization from the start, not after discovering a bug."],
      commonMistakes: ["Thinking count++ is atomic — it's not (read-modify-write). Use mutex locks or atomic operations to protect shared variables.", "Forgetting to protect ALL accesses to shared data — if one code path uses a lock but another doesn't, you still have a race condition."],
      relatedTopics: ["Mutex Locks", "Semaphores", "Threads & Multithreading"],
      externalLinks: [{ label: "Race Condition (Wiki)", url: "https://en.wikipedia.org/wiki/Race_condition" }],
      mcqs: [{ question: "What is a race condition?", options: ["A condition where threads run too fast", "When multiple threads access shared data concurrently and the outcome depends on timing", "A type of deadlock", "A compiler error"], answer: 1, explanations: ["Speed is not the issue.", "Correct — a race condition occurs when multiple threads access shared data concurrently, and the result depends on the timing of their execution. For example, two threads doing count++ simultaneously can lose an increment. The fix is mutual exclusion (mutex, atomic operations).", "Deadlock is different (threads waiting for each other).", "It's a runtime issue, not a compile-time error."], difficulty: "medium" }] },
    { id: "mutex-locks", title: "Mutex Locks", difficulty: "medium", definition: "A mutex (mutual exclusion) lock ensures only one thread enters a critical section at a time. A thread acquires the lock before entering and releases it after. If another thread tries to acquire a held lock, it blocks until released. Mutexes can cause deadlocks and priority inversion if misused. Always acquire locks in a consistent order to avoid deadlocks.",
      coreUnderstanding: "A mutex (mutual exclusion) lock ensures only one thread enters a critical section at a time. A thread acquires the lock before entering the critical section and releases it after. If another thread tries to acquire a held lock, it blocks (waits) until the lock is released. Mutexes are the most common synchronization primitive. Risks: deadlocks (circular waiting on locks) and priority inversion (a high-priority thread waits for a low-priority one holding the lock). To avoid deadlocks: always acquire locks in a consistent order. To avoid priority inversion: use priority inheritance (temporarily raise the lock holder's priority).",
      howItWorks: "1. Create: pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER.\n2. Acquire: pthread_mutex_lock(&lock) — if the lock is free, take it. If held, block (wait) until released.\n3. Critical section: the code between lock and unlock. Only one thread executes this at a time.\n4. Release: pthread_mutex_unlock(&lock) — release the lock, wake up a waiting thread.\n5. Deadlock: Thread A holds Lock1 and waits for Lock2; Thread B holds Lock2 and waits for Lock1. Both block forever.\n6. Deadlock prevention: always acquire locks in the same order (e.g., always Lock1 before Lock2).\n7. trylock: pthread_mutex_trylock(&lock) — returns immediately (doesn't block) if the lock is held. Useful for avoiding deadlocks.\n8. Timed lock: pthread_mutex_timedlock(&lock, &timeout) — blocks for at most a specified time.",
      codeExamples: [{ lang: "c", code: "#include <pthread.h>\n\nint count = 0;\npthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;\n\nvoid* increment(void* arg) {\n    for (int i = 0; i < 10000; i++) {\n        pthread_mutex_lock(&lock);    // acquire\n        count++;                      // critical section\n        pthread_mutex_unlock(&lock);  // release\n    }\n    return NULL;\n}\n\nint main() {\n    pthread_t t1, t2;\n    pthread_create(&t1, NULL, increment, NULL);\n    pthread_create(&t2, NULL, increment, NULL);\n    pthread_join(t1, NULL);\n    pthread_join(t2, NULL);\n    printf(\"count = %d\\n\", count);  // 20000 (correct!)\n    return 0;\n}\n\n// Deadlock example (BAD!):\n// Thread A: lock(L1); lock(L2); ...\n// Thread B: lock(L2); lock(L1); ...\n// Both wait forever!\n\n// Fix: consistent lock ordering\n// Thread A: lock(L1); lock(L2); ...\n// Thread B: lock(L1); lock(L2); ...  (same order!)", output: "count = 20000", note: "A mutex ensures only one thread enters a critical section. lock() blocks if held. Risks: deadlocks (acquire locks in consistent order) and priority inversion (use priority inheritance). Always pair lock() with unlock()." }],
      marginNotes: ["Always acquire locks in a CONSISTENT ORDER to avoid deadlocks. If Thread A does lock(L1) then lock(L2), and Thread B does lock(L2) then lock(L1), you get a deadlock. Both should acquire in the same order.", "Priority inversion: a high-priority thread waits for a low-priority thread holding the lock. Fix: priority inheritance — temporarily raise the lock holder's priority to match the highest waiter.", "Always pair lock() with unlock(). Use try-finally or RAII (C++ std::lock_guard) to ensure unlock runs even if an exception occurs. Forgetting to unlock causes a deadlock (all threads waiting forever)."],
      commonMistakes: ["Acquiring locks in different orders across threads — causes deadlocks. Always acquire locks in the same order.", "Forgetting to unlock a mutex — all threads waiting on that lock block forever. Use try-finally or RAII to guarantee unlock."],
      relatedTopics: ["Semaphores", "Race Conditions & Critical Sections", "Deadlocks"],
      externalLinks: [{ label: "Mutex (Wiki)", url: "https://en.wikipedia.org/wiki/Lock_(computer_science)" }],
      mcqs: [{ question: "How do you prevent mutex deadlocks?", options: ["Use more locks", "Always acquire locks in a consistent order across all threads", "Use shorter critical sections", "Avoid using locks"], answer: 1, explanations: ["More locks increase deadlock risk.", "Correct — deadlocks occur when threads acquire locks in different orders (circular wait). If all threads acquire locks in the same order (e.g., always L1 before L2), circular wait is impossible, and deadlocks can't occur.", "Shorter sections help performance but don't prevent deadlocks.", "Avoiding locks means race conditions."], difficulty: "medium" }] },
    { id: "semaphores", title: "Semaphores", difficulty: "medium", definition: "A semaphore is an integer with atomic wait (P/decrement, block if zero) and signal (V/increment, wake a waiter) operations. A binary semaphore (0 or 1) is like a mutex. A counting semaphore allows N threads into a section simultaneously — useful for resource pools (e.g., N database connections). Semaphores can also signal events between threads. Misuse causes deadlocks.",
      coreUnderstanding: "A semaphore is an integer variable with two atomic operations: wait (P/P-decrement — if value > 0, decrement and continue; if 0, block) and signal (V/increment — increment value and wake a blocked waiter). A binary semaphore (0 or 1) is like a mutex. A counting semaphore (value N) allows N threads into a section simultaneously — useful for resource pools (N database connections, N parking spots). Semaphores can also signal events (one thread signals, another waits). Semaphores are more flexible than mutexes but easier to misuse (no ownership concept, easy to forget a signal).",
      howItWorks: "1. Create: sem_init(&sem, 0, initial_value). initial_value = N (counting) or 1 (binary/mutex).\n2. wait (P): sem_wait(&sem) — if value > 0, decrement and return. If 0, block (wait for a signal).\n3. signal (V): sem_post(&sem) — increment value. If there are blocked waiters, wake one.\n4. Binary semaphore (initial 1): like a mutex. wait = lock, signal = unlock.\n5. Counting semaphore (initial N): allows N threads into a section. E.g., N=5 means 5 threads can enter; the 6th blocks.\n6. Resource pool: counting semaphore for N resources. wait = take a resource (block if none). signal = return a resource.\n7. Event signaling: one thread waits, another signals. Not mutual exclusion — just coordination.\n8. Misuse: forgetting to signal (deadlock), signaling without a waiter (lost wakeup — usually OK with counting semaphores).",
      codeExamples: [{ lang: "c", code: "#include <semaphore.h>\n#include <pthread.h>\n\n// Counting semaphore: resource pool (3 connections)\nsem_t connections;\nsem_init(&connections, 0, 3);  // 3 available\n\nvoid* use_database(void* arg) {\n    sem_wait(&connections);    // take a connection (blocks if 0)\n    // ... use database (only 3 threads here at a time) ...\n    printf(\"Using connection\\n\");\n    sem_post(&connections);    // return a connection\n    return NULL;\n}\n\n// Binary semaphore (like a mutex)\nsem_t mutex;\nsem_init(&mutex, 0, 1);  // 1 = available\n\nvoid critical_section() {\n    sem_wait(&mutex);    // lock\n    // ... critical section ...\n    sem_post(&mutex);    // unlock\n}\n\n// Event signaling: one thread waits, another signals\nsem_t event;\nsem_init(&event, 0, 0);  // 0 = no event yet\n\nvoid* waiter() {\n    sem_wait(&event);  // blocks until signaled\n    printf(\"Event received!\\n\");\n    return NULL;\n}\n\nvoid* signaler() {\n    // ... do work ...\n    sem_post(&event);  // signal the waiter\n    return NULL;\n}", output: "(semaphore usage)", note: "A semaphore has wait (P: decrement, block if 0) and signal (V: increment, wake a waiter). Binary (0/1) = like mutex. Counting (N) = resource pool. Can also signal events. Misuse causes deadlocks." }],
      marginNotes: ["A binary semaphore (0 or 1) is like a mutex, but with a key difference: a mutex has ownership (the thread that locked it must unlock it). A semaphore has no ownership — any thread can signal. This makes semaphores more flexible but easier to misuse.", "Counting semaphores are perfect for resource pools: N database connections, N parking spots, N print jobs. wait = take a resource (block if none), signal = return a resource.", "Semaphore misuse: forgetting to signal (waiters block forever), or signaling in the wrong place. Semaphores don't have ownership, so debugging is harder than with mutexes."],
      commonMistakes: ["Confusing binary semaphores with mutexes — a mutex has ownership (only the locker can unlock), a semaphore doesn't (any thread can signal). This makes mutexes safer for mutual exclusion.", "Forgetting to signal a semaphore — waiters block forever. Always ensure every wait has a corresponding signal on all code paths (use try-finally)."],
      relatedTopics: ["Mutex Locks", "Race Conditions & Critical Sections", "Producer-Consumer Problem"],
      externalLinks: [{ label: "Semaphore (Wiki)", url: "https://en.wikipedia.org/wiki/Semaphore_(programming)" }],
      mcqs: [{ question: "What is the difference between a binary semaphore and a counting semaphore?", options: ["Binary is faster", "Binary (0/1) is like a mutex; counting (value N) allows N threads into a section simultaneously", "Binary is for threads; counting is for processes", "They are the same"], answer: 1, explanations: ["Speed is not the difference.", "Correct — a binary semaphore (value 0 or 1) is like a mutex (mutual exclusion). A counting semaphore (value N) allows N threads into a section simultaneously — useful for resource pools (N connections, N parking spots).", "Both work with threads and processes.", "They serve different purposes."], difficulty: "medium" }] },
    { id: "monitors", title: "Monitors", difficulty: "medium", definition: "A monitor is a high-level synchronization construct — an object/module where only one thread can be active inside at a time (automatic mutual exclusion). Condition variables (wait/signal) inside monitors let threads wait for specific conditions and be woken when conditions change. Java's synchronized methods and Python's threading.Condition are monitor-like. Monitors are safer than raw semaphores because the locking is automatic.",
      coreUnderstanding: "A monitor is a high-level synchronization construct: an object/module where only one thread can be active inside at a time (automatic mutual exclusion — the compiler/runtime handles locking). Inside the monitor, condition variables let threads wait for specific conditions and be woken when conditions change. wait() releases the lock and blocks; signal() wakes a waiting thread. Monitors are safer than raw semaphores because the locking is automatic (you can't forget to lock/unlock). Java's synchronized methods and Python's threading.Condition are monitor-like. The producer-consumer pattern is the classic monitor use case.",
      howItWorks: "1. A monitor is a module/class with: shared data, procedures (methods), condition variables.\n2. Automatic mutual exclusion: only one thread can be inside any of the monitor's methods at a time. The lock is acquired automatically on entry and released on exit.\n3. Condition variables: for waiting on conditions. wait(cv) releases the monitor lock and blocks. signal(cv) wakes one waiting thread. signal_all(cv) wakes all.\n4. wait() atomically: releases the lock, blocks the thread. When signaled, reacquires the lock and continues.\n5. signal(): wakes one waiting thread (if any). The woken thread must reacquire the lock before continuing.\n6. Producer-Consumer: producer signals 'not empty' after adding; consumer signals 'not full' after removing. Both wait on their respective conditions.\n7. Java: synchronized methods are monitor-like (automatic mutual exclusion). Object.wait() and Object.notify() are condition variables.",
      codeExamples: [{ lang: "java", code: "// Java monitor (synchronized + wait/notify)\nclass BoundedBuffer<T> {\n    private final T[] buffer;\n    private int count = 0, in = 0, out = 0;\n    \n    public BoundedBuffer(int size) {\n        buffer = (T[]) new Object[size];\n    }\n    \n    // Automatic mutual exclusion (synchronized)\n    public synchronized void put(T item) throws InterruptedException {\n        while (count == buffer.length) {\n            wait();  // buffer full -> wait (releases lock)\n        }\n        buffer[in] = item;\n        in = (in + 1) % buffer.length;\n        count++;\n        notifyAll();  // signal consumers: not empty\n    }\n    \n    public synchronized T take() throws InterruptedException {\n        while (count == 0) {\n            wait();  // buffer empty -> wait\n        }\n        T item = buffer[out];\n        out = (out + 1) % buffer.length;\n        count--;\n        notifyAll();  // signal producers: not full\n        return item;\n    }\n}\n\n// Monitor = synchronized (automatic lock) + wait/notify (condition variables)\n// Safer than semaphores: can't forget to lock/unlock\n// The while loop (not if) handles spurious wakeups", output: "(bounded buffer)", note: "A monitor provides automatic mutual exclusion (synchronized) + condition variables (wait/notify). wait() releases the lock and blocks; signal/notify wakes a waiter. Safer than semaphores (can't forget to lock). Java's synchronized is monitor-like." }],
      marginNotes: ["Monitors are safer than semaphores because the locking is automatic — the compiler/runtime handles it. You can't forget to lock or unlock, which eliminates a whole class of bugs.", "Always use while (not if) when checking conditions before wait(). This handles spurious wakeups (some systems wake threads without a signal) and ensures the condition is still true after waking.", "Java's synchronized methods provide automatic mutual exclusion (monitor-like). Object.wait() and Object.notify()/notifyAll() are the condition variables. Python's threading.Condition provides similar functionality."],
      commonMistakes: ["Using if instead of while when checking conditions before wait() — spurious wakeups can cause the thread to proceed even though the condition is false. Always use while.", "Forgetting to call notify/notifyAll after changing state — waiting threads never wake. Use notifyAll() (not notify()) when multiple conditions might be affected."],
      relatedTopics: ["Mutex Locks", "Semaphores", "Producer-Consumer Problem"],
      externalLinks: [{ label: "Monitor (Wiki)", url: "https://en.wikipedia.org/wiki/Monitor_(synchronization)" }],
      mcqs: [{ question: "What advantage does a monitor have over raw semaphores?", options: ["It's faster", "Automatic mutual exclusion — the locking is handled automatically, so you can't forget to lock/unlock", "It uses less memory", "It supports more threads"], answer: 1, explanations: ["Speed is not the key advantage.", "Correct — a monitor provides automatic mutual exclusion: the compiler/runtime acquires the lock on entry to a method and releases it on exit. You can't forget to lock or unlock, which eliminates a whole class of bugs that semaphores are prone to.", "Memory is similar.", "Thread count is not the difference."], difficulty: "medium" }] },
    { id: "deadlocks", title: "Deadlocks", difficulty: "hard", definition: "A deadlock is a state where a set of processes are each waiting for a resource held by another in the set, so none can proceed. Four conditions must hold simultaneously (Coffman conditions): mutual exclusion, hold and wait, no preemption, and circular wait. Breaking any one prevents deadlocks. Detection, prevention, avoidance (Banker's algorithm), and ostrich (ignore) are the strategies.",
      coreUnderstanding: "A deadlock is a state where a set of processes are each waiting for a resource held by another in the set, so none can proceed — a circular wait. Four conditions (Coffman conditions) must ALL hold simultaneously for a deadlock: (1) Mutual exclusion — resources can't be shared. (2) Hold and wait — a process holds one resource while waiting for another. (3) No preemption — resources can't be forcibly taken. (4) Circular wait — P1 waits for P2's resource, P2 waits for P3's, ..., Pn waits for P1's. Breaking any one condition prevents deadlocks. Strategies: prevention (break a condition), avoidance (Banker's algorithm — check safe state), detection (find and resolve), and ostrich (ignore — most OSes do this for user processes).",
      howItWorks: "1. Coffman conditions (all four must hold for deadlock):\n   a. Mutual exclusion: resources can't be shared (a printer can only print one job at a time).\n   b. Hold and wait: a process holds a resource while waiting for another.\n   c. No preemption: resources can't be forcibly taken (only released voluntarily).\n   d. Circular wait: P1 -> P2 -> ... -> Pn -> P1 (circular dependency).\n2. Prevention: break one condition. E.g., resource ordering breaks circular wait (always acquire in order L1, L2, L3).\n3. Avoidance (Banker's algorithm): before granting a resource, check if the system remains in a safe state (all processes can eventually complete). Requires knowing future requests.\n4. Detection: periodically check for circular wait in the resource allocation graph. If found, kill a process to break the cycle.\n5. Ostrich: ignore deadlocks (most OSes do this for user processes — deadlocks are rare enough that the cost of prevention isn't worth it).",
      codeExamples: [{ lang: "c", code: "// Deadlock example: two threads, two locks\npthread_mutex_t lock1 = PTHREAD_MUTEX_INITIALIZER;\npthread_mutex_t lock2 = PTHREAD_MUTEX_INITIALIZER;\n\nvoid* thread_a(void* arg) {\n    pthread_mutex_lock(&lock1);  // A holds lock1\n    // ... some work ...\n    pthread_mutex_lock(&lock2);  // A waits for lock2 (held by B!)\n    // ... critical section ...\n    pthread_mutex_unlock(&lock2);\n    pthread_mutex_unlock(&lock1);\n    return NULL;\n}\n\nvoid* thread_b(void* arg) {\n    pthread_mutex_lock(&lock2);  // B holds lock2\n    // ... some work ...\n    pthread_mutex_lock(&lock1);  // B waits for lock1 (held by A!)\n    // ... critical section ...\n    pthread_mutex_unlock(&lock1);\n    pthread_mutex_unlock(&lock2);\n    return NULL;\n}\n// DEADLOCK: A holds lock1, waits for lock2.\n//           B holds lock2, waits for lock1.\n//           Neither can proceed.\n\n// FIX: consistent lock ordering\nvoid* thread_b_fixed(void* arg) {\n    pthread_mutex_lock(&lock1);  // B acquires lock1 FIRST (same as A)\n    pthread_mutex_lock(&lock2);  // then lock2\n    // ... critical section ...\n    pthread_mutex_unlock(&lock2);\n    pthread_mutex_unlock(&lock1);\n    return NULL;\n}\n// No circular wait -> no deadlock!", output: "(deadlock example)", note: "Deadlock: circular wait (A holds L1, waits for L2; B holds L2, waits for L1). Four Coffman conditions must all hold. Fix: consistent lock ordering (breaks circular wait). Most OSes use the ostrich approach (ignore) for user processes." }],
      marginNotes: ["The four Coffman conditions must ALL hold for a deadlock. Break any one to prevent deadlocks. The easiest to break is circular wait: enforce a global lock ordering (always acquire locks in the same order).", "Most OSes use the ostrich approach for user processes: ignore deadlocks. Deadlocks are rare enough that the cost of prevention/avoidance/detection isn't worth the performance overhead. If a deadlock occurs, the user restarts the program.", "Banker's algorithm (avoidance): before granting a resource, check if the system remains in a safe state (all processes can eventually complete). It requires knowing future resource requests, which limits practical use. Used in some real-time/embedded systems."],
      commonMistakes: ["Acquiring locks in different orders across threads — causes circular wait (deadlock). Always acquire locks in the same order.", "Thinking deadlocks are always detected — most OSes ignore them (ostrich approach). The program just hangs, and the user restarts it."],
      relatedTopics: ["Mutex Locks", "Deadlock Prevention & Avoidance", "Dining Philosophers Problem"],
      externalLinks: [{ label: "Deadlock (Wiki)", url: "https://en.wikipedia.org/wiki/Deadlock" }],
      mcqs: [{ question: "How many Coffman conditions must hold simultaneously for a deadlock?", options: ["One", "Two", "Three", "All four: mutual exclusion, hold and wait, no preemption, circular wait"], answer: 3, explanations: ["One is not enough.", "Two is not enough.", "Three is not enough.", "Correct — ALL four Coffman conditions must hold simultaneously for a deadlock: mutual exclusion, hold and wait, no preemption, and circular wait. Breaking any ONE condition prevents deadlocks. The easiest to break is circular wait (enforce lock ordering)."], difficulty: "medium" }] },
    { id: "deadlock-prevention", title: "Deadlock Prevention & Avoidance", difficulty: "hard", definition: "Prevention ensures at least one Coffman condition can't hold: enforce resource ordering (break circular wait), request all resources at once (break hold-and-wait), or preempt. Avoidance (Banker's algorithm) dynamically checks if granting a resource keeps the system in a safe state — one where all processes can eventually complete. Avoidance requires knowing future resource requests, which limits practical use.",
      coreUnderstanding: "Deadlock prevention and avoidance are two strategies to eliminate deadlocks. Prevention: statically ensure at least one Coffman condition can't hold. The most practical is breaking circular wait: enforce a global resource ordering (always acquire resources in increasing order). Avoidance: dynamically check if granting a resource keeps the system in a safe state (one where all processes can eventually complete). The Banker's algorithm is the classic avoidance algorithm — it checks if there's a safe sequence after each resource request. Avoidance requires knowing future resource requests, which limits practical use. Most OSes use neither — they use the ostrich approach (ignore deadlocks).",
      howItWorks: "1. Prevention (break a Coffman condition):\n   a. Break mutual exclusion: make resources shareable (spool print jobs instead of exclusive printer). Not always possible.\n   b. Break hold and wait: request ALL resources at once (before starting). Wasteful (hold resources you don't need yet).\n   c. Break no preemption: allow the OS to take resources away (risky — can corrupt state).\n   d. Break circular wait: enforce a global resource ordering. Always acquire resources in increasing order (L1 before L2 before L3). Most practical.\n2. Avoidance (Banker's algorithm):\n   a. Each process declares its maximum resource needs upfront.\n   b. Before granting a resource, check if the system remains in a safe state.\n   c. Safe state: there exists a sequence where all processes can complete.\n   d. If granting would lead to an unsafe state, the process waits.\n3. Detection: periodically check for circular wait. If found, kill a process (victim selection) to break the cycle.\n4. Ostrich: ignore deadlocks. Most OSes do this — deadlocks are rare enough that prevention isn't worth the overhead.",
      codeExamples: [{ lang: "text", code: "Deadlock Prevention Strategies:\n\n1. Break Circular Wait (most practical):\n   Assign a global order to all resources.\n   Threads must acquire in increasing order.\n   \n   Resources: R1 < R2 < R3\n   Thread A: lock(R1), lock(R2), lock(R3)  ✓\n   Thread B: lock(R1), lock(R3)             ✓\n   // No circular wait possible!\n\n2. Break Hold and Wait:\n   Thread must request ALL resources at once.\n   Thread A: request(R1, R2, R3)  // gets all or none\n   // Wasteful: holds R1 while not using it\n\n3. Break No Preemption:\n   OS can take resources away.\n   // Risky: can corrupt process state\n\nDeadlock Avoidance (Banker's Algorithm):\n\n  Processes declare max needs.\n  Before granting, check: is there a safe sequence?\n  \n  Example: 3 processes, 10 resource units\n  P1: max=9, held=3, need=6\n  P2: max=4, held=2, need=2\n  P3: max=7, held=2, need=5\n  Available: 10 - 3 - 2 - 2 = 3\n  \n  Safe sequence: P2 (need=2, avail=3) -> avail=5\n                  P1 (need=6, avail=5? NO)\n                  P3 (need=5, avail=5) -> avail=7\n                  P1 (need=6, avail=7) -> avail=10\n  Safe! Grant the resource.", output: "(prevention/avoidance)", note: "Prevention: break a Coffman condition (circular wait via resource ordering is most practical). Avoidance: Banker's algorithm checks safe state before granting (needs future knowledge). Detection: find and kill. Ostrich: ignore (most OSes)." }],
      marginNotes: ["The most practical prevention is breaking circular wait: enforce a global resource ordering (always acquire locks in the same order). This is simple, effective, and used in practice.", "Banker's algorithm (avoidance) requires knowing each process's maximum resource needs upfront. This is impractical for general-purpose OSes (processes don't declare needs). It's used in some real-time/embedded systems with known workloads.", "Most OSes use the ostrich approach: ignore deadlocks. Deadlocks are rare in practice, and the overhead of prevention/avoidance/detection isn't worth it. If a deadlock occurs, the user restarts the program."],
      commonMistakes: ["Thinking Banker's algorithm is practical for general OSes — it requires knowing future resource requests, which processes don't declare. It's mainly of theoretical interest and used in specialized systems.", "Forgetting that prevention has trade-offs: resource ordering is simple but can reduce concurrency (threads wait for lower-numbered resources they don't need)."],
      relatedTopics: ["Deadlocks", "Mutex Locks", "Dining Philosophers Problem"],
      externalLinks: [{ label: "Banker's Algorithm (Wiki)", url: "https://en.wikipedia.org/wiki/Banker%27s_algorithm" }],
      mcqs: [{ question: "Which deadlock prevention strategy is most practical?", options: ["Break mutual exclusion", "Break no preemption", "Break circular wait by enforcing a global resource ordering", "Break hold and wait by requesting all at once"], answer: 2, explanations: ["Mutual exclusion can't always be broken (some resources are inherently non-shareable).", "Preemption is risky (can corrupt process state).", "Correct — breaking circular wait by enforcing a global resource ordering (always acquire locks in the same order) is the most practical prevention strategy. It's simple, effective, and widely used.", "Requesting all at once is wasteful (holds resources you don't need yet)."], difficulty: "hard" }] },
    { id: "dining-philosophers", title: "Dining Philosophers Problem", difficulty: "hard", definition: "Five philosophers sit at a table with five forks, each needing two forks to eat. If all grab their left fork simultaneously and wait for the right, deadlock occurs. Solutions: resource hierarchy (always pick up lower-numbered fork first), arbitrator (waiter), or limiting concurrent diners. It's a classic model for resource sharing and deadlock in concurrent systems.",
      coreUnderstanding: "The Dining Philosophers Problem: 5 philosophers sit at a table with 5 forks (one between each pair). Each philosopher needs 2 forks to eat. If all grab their left fork simultaneously, they all wait for the right fork — deadlock. This models resource sharing in concurrent systems: multiple processes needing multiple shared resources. Solutions: (1) Resource hierarchy — always pick up the lower-numbered fork first (breaks circular wait). (2) Arbitrator (waiter) — ask a central authority for permission. (3) Limit concurrent diners — allow at most 4 to pick up forks (at least one can get both). (4) Asymmetry — odd philosophers pick left first, even pick right first.",
      howItWorks: "1. Setup: 5 philosophers, 5 forks. Each philosopher: think -> pick up left fork -> pick up right fork -> eat -> put down forks -> repeat.\n2. Deadlock: all 5 pick up their left fork simultaneously. All wait for the right fork (held by their neighbor). Circular wait -> deadlock.\n3. Solution 1 (Resource Hierarchy): number forks 0-4. Always pick up the lower-numbered fork first. Philosopher 4 picks up fork 0 (not fork 4) first — breaks the cycle.\n4. Solution 2 (Arbitrator): a waiter (semaphore with initial 4) allows at most 4 philosophers to pick up forks. At least one gets both.\n5. Solution 3 (Asymmetry): odd philosophers pick left first, even pick right first. Breaks symmetry — no circular wait.\n6. Solution 4 (Try-lock): pick up left fork; try to pick up right fork; if unavailable, put down left and wait. Livelock risk (all keep trying simultaneously).",
      codeExamples: [{ lang: "c", code: "// Dining Philosophers: Resource Hierarchy Solution\n#include <pthread.h>\n\npthread_mutex_t forks[5];\n\nvoid* philosopher(void* arg) {\n    int id = *(int*)arg;\n    int left = id;\n    int right = (id + 1) % 5;\n    \n    // Resource hierarchy: always pick up lower-numbered fork first\n    int first = (left < right) ? left : right;\n    int second = (left < right) ? right : left;\n    \n    while (1) {\n        think();\n        pthread_mutex_lock(&forks[first]);   // lower-numbered first\n        pthread_mutex_lock(&forks[second]);  // then higher-numbered\n        eat();\n        pthread_mutex_unlock(&forks[second]);\n        pthread_mutex_unlock(&forks[first]);\n    }\n    return NULL;\n}\n\n// Philosopher 4: left=4, right=0\n// first = 0 (lower), second = 4 (higher)\n// Picks up fork 0 first, not fork 4!\n// This breaks the circular wait.\n\n// Other solutions:\n// - Arbitrator: sem_t room; sem_init(&room, 0, 4); // max 4 dining\n// - Asymmetry: odd pick left first, even pick right first\n// - Chandy/Misra: tokens and dirty/clean forks (distributed)", output: "(philosopher solution)", note: "Dining Philosophers: 5 philosophers, 5 forks, need 2 to eat. Deadlock if all grab left fork simultaneously. Solutions: resource hierarchy (lower-numbered first), arbitrator (max 4), asymmetry (odd/even). Breaks circular wait." }],
      marginNotes: ["The resource hierarchy solution is the simplest and most practical: number all resources and always acquire in increasing order. This breaks circular wait — one of the four Coffman conditions.", "The arbitrator (waiter) solution uses a counting semaphore with initial value N-1 (4 for 5 philosophers). This ensures at least one philosopher can get both forks. Simple but reduces concurrency.", "The Dining Philosophers models real-world resource sharing: processes needing multiple locks. The solutions (resource ordering, limiting concurrency, asymmetry) are directly applicable to real concurrent programming."],
      commonMistakes: ["Forgetting that the naive solution (pick up left, then right) causes deadlock when all pick up simultaneously. Always use one of the deadlock-free solutions.", "Using try-lock (pick up left, try right, if fail put down left) — this can cause livelock (all keep trying simultaneously and failing). Add random delays to break the symmetry."],
      relatedTopics: ["Deadlocks", "Deadlock Prevention & Avoidance", "Semaphores"],
      externalLinks: [{ label: "Dining Philosophers (Wiki)", url: "https://en.wikipedia.org/wiki/Dining_philosophers_problem" }],
      mcqs: [{ question: "What causes deadlock in the naive Dining Philosophers solution?", options: ["Too many philosophers", "All philosophers pick up their left fork simultaneously, then wait for the right fork (circular wait)", "Not enough food", "The table is too small"], answer: 1, explanations: ["The number of philosophers is the setup, not the cause.", "Correct — if all 5 philosophers pick up their left fork simultaneously, they all wait for the right fork (held by their neighbor). This is a circular wait — one of the four Coffman conditions. The fix is to break circular wait (e.g., resource hierarchy: pick up the lower-numbered fork first).", "Food is not the issue.", "Table size is irrelevant."], difficulty: "medium" }] },
    { id: "producer-consumer", title: "Producer-Consumer Problem", difficulty: "medium", definition: "Producers generate data and put it in a shared buffer; consumers remove and process it. The buffer is bounded, so producers must wait when full and consumers must wait when empty. Solved with a counting semaphore (free slots), a counting semaphore (filled slots), and a mutex (buffer access). This is the canonical bounded-buffer problem in concurrency.",
      coreUnderstanding: "The Producer-Consumer problem: producers generate data and put it in a bounded buffer; consumers remove and process it. The buffer has limited capacity, so producers must wait when full, and consumers must wait when empty. The solution uses three synchronization primitives: (1) A counting semaphore 'empty' (initial = N) for free slots — producers wait on it. (2) A counting semaphore 'full' (initial = 0) for filled slots — consumers wait on it. (3) A mutex (initial = 1) for mutual exclusion on buffer access. This is the canonical bounded-buffer problem in concurrency and models real-world pipelines (request queues, event systems, streaming).",
      howItWorks: "1. Semaphores: empty (counting, initial = N) — free slots. full (counting, initial = 0) — filled slots. mutex (binary, initial = 1) — buffer access.\n2. Producer: wait(empty) [decrement free slots, block if 0] -> wait(mutex) [lock buffer] -> add item -> signal(mutex) [unlock] -> signal(full) [increment filled slots, wake consumer].\n3. Consumer: wait(full) [decrement filled slots, block if 0] -> wait(mutex) [lock buffer] -> remove item -> signal(mutex) [unlock] -> signal(empty) [increment free slots, wake producer].\n4. Order matters: wait(empty/full) BEFORE wait(mutex). If you lock the mutex first and the buffer is full, you deadlock (holding the lock while waiting for space).\n5. Monitors: alternative solution with condition variables (not_full, not_empty) inside a synchronized block.",
      codeExamples: [{ lang: "c", code: "#include <semaphore.h>\n#include <pthread.h>\n\n#define N 5  // buffer size\nint buffer[N];\nint in = 0, out = 0;\n\nsem_t empty;  // free slots (initial N)\nsem_t full;   // filled slots (initial 0)\nsem_t mutex;  // buffer access (initial 1)\n\nvoid init() {\n    sem_init(&empty, 0, N);  // N free slots\n    sem_init(&full, 0, 0);   // 0 filled slots\n    sem_init(&mutex, 0, 1);  // 1 = unlocked\n}\n\nvoid* producer(void* arg) {\n    int item = 0;\n    while (1) {\n        item = produce();\n        sem_wait(&empty);   // wait for free slot\n        sem_wait(&mutex);    // lock buffer\n        buffer[in] = item;\n        in = (in + 1) % N;\n        sem_post(&mutex);   // unlock buffer\n        sem_post(&full);    // signal: one more filled\n    }\n    return NULL;\n}\n\nvoid* consumer(void* arg) {\n    int item;\n    while (1) {\n        sem_wait(&full);     // wait for filled slot\n        sem_wait(&mutex);    // lock buffer\n        item = buffer[out];\n        out = (out + 1) % N;\n        sem_post(&mutex);    // unlock buffer\n        sem_post(&empty);    // signal: one more free\n        consume(item);\n    }\n    return NULL;\n}", output: "(producer-consumer)", note: "Producer-Consumer uses 3 semaphores: empty (free slots), full (filled slots), mutex (buffer access). Order matters: wait(empty/full) BEFORE wait(mutex) to avoid deadlock. This is the canonical bounded-buffer problem." }],
      marginNotes: ["Order matters: wait(empty/full) BEFORE wait(mutex). If you lock the mutex first and the buffer is full, the producer holds the lock while waiting for space — the consumer can't get the lock to free space. Deadlock.", "The Producer-Consumer pattern is everywhere: message queues (RabbitMQ, Kafka), thread pools (task queue), event loops (event queue), pipelined processing. Understanding the semaphore solution helps understand all of them.", "Java's BlockingQueue (ArrayBlockingQueue, LinkedBlockingQueue) implements this pattern internally. You don't need to manage semaphores yourself — just use put() and take(), which block when full/empty."],
      commonMistakes: ["Locking the mutex before waiting on empty/full — causes deadlock (holds the lock while waiting; the other side can't get the lock to make progress).", "Using signal instead of broadcast/notifyAll in the monitor version — can miss wakeups if the wrong condition is signaled."],
      relatedTopics: ["Semaphores", "Monitors", "Race Conditions & Critical Sections"],
      externalLinks: [{ label: "Producer-Consumer (Wiki)", url: "https://en.wikipedia.org/wiki/Producer%E2%80%93consumer_problem" }],
      mcqs: [{ question: "Why must you wait on the counting semaphore BEFORE locking the mutex in Producer-Consumer?", options: ["It's faster", "If you lock the mutex first and the buffer is full, you deadlock — holding the lock while waiting for space, while the consumer can't get the lock to free space", "It uses less memory", "It's the convention"], answer: 1, explanations: ["Speed is not the reason.", "Correct — if the producer locks the mutex first, then waits for a free slot (which requires the consumer to remove an item), but the consumer can't get the mutex to remove an item — deadlock. Always wait on the counting semaphore (empty/full) BEFORE locking the mutex.", "Memory is unrelated.", "It's not just convention — it prevents deadlock."], difficulty: "hard" }] },
    { id: "readers-writers", title: "Readers-Writers Problem", difficulty: "hard", definition: "Multiple readers can read a shared resource simultaneously, but a writer needs exclusive access. The challenge: if readers keep arriving, writers starve (reader-priority version), or if writers have priority, readers starve. Solutions use semaphores and a read counter with careful ordering to balance fairness. This models databases, file systems, and caches.",
      coreUnderstanding: "The Readers-Writers problem: multiple readers can read a shared resource simultaneously (safe — reads don't modify), but a writer needs exclusive access (no other readers or writers). The challenge: if readers keep arriving, writers starve (reader-priority version) — a stream of readers prevents any writer from writing. If writers have priority, readers starve. Solutions use semaphores and a read counter with careful ordering to balance fairness. This models databases (read transactions vs write transactions), file systems (read vs write locks), and caches. The key tension: maximizing concurrency (many readers) vs fairness (writers eventually get to write).",
      howItWorks: "1. Reader-priority version: readers can always read if no writer is writing. Risk: writer starvation (readers keep arriving, writer never gets exclusive access).\n2. Writer-priority version: if a writer is waiting, new readers must wait. Risk: reader starvation (writers keep arriving, readers never read).\n3. First reader: locks the resource (read lock). Subsequent readers can enter without locking (they increment a counter).\n4. Last reader: unlocks the resource (read lock released, writers can proceed).\n5. Writer: needs exclusive lock. Waits until all readers have left.\n6. Semaphores: mutex (protects readcount), rw_mutex (read/write access). readcount (number of active readers).\n7. Fair solutions: use a turnstile semaphore so writers can block new readers when waiting. This prevents starvation.",
      codeExamples: [{ lang: "c", code: "// Readers-Writers (reader-priority)\n#include <semaphore.h>\n#include <pthread.h>\n\nsem_t mutex;    // protects readcount (initial 1)\nsem_t rw_mutex; // read/write access (initial 1)\nint readcount = 0;  // number of active readers\n\nvoid* reader(void* arg) {\n    sem_wait(&mutex);\n    readcount++;\n    if (readcount == 1)  // first reader locks\n        sem_wait(&rw_mutex);\n    sem_post(&mutex);\n    \n    // ... read the shared resource ...\n    // (multiple readers can be here simultaneously)\n    \n    sem_wait(&mutex);\n    readcount--;\n    if (readcount == 0)  // last reader unlocks\n        sem_post(&rw_mutex);\n    sem_post(&mutex);\n    return NULL;\n}\n\nvoid* writer(void* arg) {\n    sem_wait(&rw_mutex);  // exclusive access\n    \n    // ... write to the shared resource ...\n    // (only one writer, no readers)\n    \n    sem_post(&rw_mutex);\n    return NULL;\n}\n\n// Problem: if readers keep arriving, writers STARVE.\n// Fix (turnstile): writers block new readers:\n//   sem_wait(&turnstile);  // writer blocks new readers\n//   sem_wait(&turnstile);  // reader checks, then proceeds\n//   ... read ...\n//   sem_post(&turnstile);", output: "(readers-writers)", note: "Readers-Writers: many readers can read simultaneously, but writers need exclusive access. Risk: starvation (reader-priority starves writers, writer-priority starves readers). Fix: turnstile semaphore for fairness. Models databases, file systems, caches." }],
      marginNotes: ["Reader-priority: readers can always read if no writer is writing. Risk: writer starvation (a stream of readers prevents any writer from getting exclusive access).", "Writer-priority: if a writer is waiting, new readers must wait. Risk: reader starvation. The trade-off is between maximizing read concurrency and ensuring writers eventually write.", "The turnstile solution: a writer waiting blocks new readers from entering (via a turnstile semaphore). This prevents writer starvation while allowing concurrent reads when no writer is waiting. Java's ReentrantReadWriteLock implements this pattern."],
      commonMistakes: ["Using a simple mutex for both reads and writes — serializes all reads (no concurrency). Use a read-write lock (ReentrantReadWriteLock) to allow concurrent reads.", "Forgetting about starvation — reader-priority starves writers, writer-priority starves readers. Use a turnstile or timeout to ensure fairness."],
      relatedTopics: ["Semaphores", "Mutex Locks", "Monitors"],
      externalLinks: [{ label: "Readers-Writers (Wiki)", url: "https://en.wikipedia.org/wiki/Readers%E2%80%93writers_problem" }],
      mcqs: [{ question: "What is the main challenge in the Readers-Writers problem?", options: ["Readers are slow", "Balancing concurrency (many readers) with fairness (writers eventually get to write, no starvation)", "Writers are faster than readers", "The buffer is too small"], answer: 1, explanations: ["Reader speed is not the challenge.", "Correct — multiple readers can read simultaneously (good concurrency), but writers need exclusive access. The challenge is ensuring writers eventually get to write (no starvation from a stream of readers) while still maximizing read concurrency.", "Relative speed is irrelevant.", "There is no buffer in the classic problem."], difficulty: "medium" }] },
    { id: "memory-management", title: "Memory Management", difficulty: "medium", definition: "Memory management allocates and tracks the computer's main memory among competing processes. The OS must track which parts are free/used, allocate and deallocate as processes come and go, and provide each process its own address space. Key techniques: contiguous allocation, paging, segmentation, and virtual memory. The goal: efficient, safe, and transparent memory use.",
      coreUnderstanding: "Memory management is the OS's job of allocating and tracking RAM among competing processes. Goals: (1) Allocate memory to processes when they need it. (2) Track which parts are free and which are used. (3) Provide each process its own isolated address space (one process can't access another's memory). (4) Efficiently use physical memory (minimize waste). Techniques evolved over time: contiguous allocation (simple, fragmentation), paging (fixed-size blocks, no external fragmentation), segmentation (variable-size logical segments), and virtual memory (use disk as overflow, only active pages in RAM). Modern OSes use a combination of paging and virtual memory.",
      howItWorks: "1. Address space: each process has its own virtual address space (code, data, heap, stack). The OS maps virtual to physical addresses.\n2. Contiguous allocation: each process gets a single contiguous block. Simple but suffers from external fragmentation (holes between processes).\n3. Paging: divide memory into fixed-size blocks (pages/frames). Any page can go in any frame. No external fragmentation. Slight internal fragmentation (last page partially used).\n4. Segmentation: divide a program into logical segments (code, data, stack). Variable sizes. Suffers from external fragmentation.\n5. Virtual memory: only active pages are in RAM; the rest are on disk (swap). Page faults bring in needed pages. Allows programs larger than physical RAM.\n6. MMU (Memory Management Unit): hardware that translates virtual to physical addresses using the page table. Fast (cached in TLB).\n7. Protection: each process's page table only maps to its own physical frames — processes are isolated.",
      codeExamples: [{ lang: "text", code: "Memory Management Evolution:\n\n1. Contiguous Allocation (simplest):\n   [OS][Process A][free][Process B][free][Process C]\n   Problem: external fragmentation (holes between processes)\n\n2. Paging (modern standard):\n   Divide memory into fixed-size blocks (4KB pages)\n   Process A's pages can go anywhere (non-contiguous)\n   Page table maps: Page 0 -> Frame 5, Page 1 -> Frame 12, etc.\n   No external fragmentation. Slight internal (last page).\n\n3. Segmentation:\n   Divide program into logical segments (code, data, stack)\n   Variable sizes. Maps to physical addresses via segment table.\n   Problem: external fragmentation (like contiguous)\n\n4. Virtual Memory (on top of paging):\n   Only active pages in RAM; rest on disk (swap space)\n   Page fault: access a page not in RAM -> OS loads it from disk\n   Allows programs larger than physical RAM\n   Provides isolation (each process has its own page table)\n\nModern OSes use: paging + virtual memory\nMMU (hardware) translates virtual -> physical via page table\nTLB (hardware cache) speeds up translation (~99% hit rate)", output: "(memory management)", note: "Memory management: allocate, track, and isolate memory. Techniques: contiguous (fragmentation), paging (fixed-size, no external frag), segmentation (logical), virtual memory (disk overflow). Modern: paging + virtual memory." }],
      marginNotes: ["The MMU (Memory Management Unit) is hardware that translates virtual to physical addresses using the page table. The TLB (Translation Lookaside Buffer) caches recent translations for speed (~99% hit rate).", "Virtual memory gives each process the illusion of a large, contiguous, private address space. Only active pages are in RAM; the rest are on disk. This allows running programs larger than physical RAM.", "Memory isolation: each process has its own page table, mapping only to its own physical frames. Process A can't access Process B's memory — the page table doesn't have those mappings. This is enforced by the MMU in hardware."],
      commonMistakes: ["Confusing virtual and physical addresses — a process sees virtual addresses (0 to 2^N-1); the MMU translates them to physical addresses (actual RAM locations).", "Thinking programs need to fit in RAM — with virtual memory, only active pages need to be in RAM. The rest can be on disk (swap)."],
      relatedTopics: ["Paging", "Virtual Memory", "Contiguous Memory Allocation"],
      externalLinks: [{ label: "Memory Management (Wiki)", url: "https://en.wikipedia.org/wiki/Memory_management" }],
      mcqs: [{ question: "What is the main goal of memory management?", options: ["Make memory faster", "Allocate, track, and isolate memory among processes efficiently and safely", "Compress memory", "Encrypt memory"], answer: 1, explanations: ["Speed is a hardware concern, not the OS's main goal.", "Correct — the OS allocates memory to processes, tracks free/used parts, and provides each process its own isolated address space. This ensures efficient use and safety (one process can't access another's memory).", "Compression is not the main goal.", "Encryption is not the main goal."], difficulty: "easy" }] },
    { id: "contiguous-allocation", title: "Contiguous Memory Allocation", difficulty: "medium", definition: "In contiguous allocation, each process gets a single contiguous block of memory. As processes load and unload, free memory fragments into small non-contiguous holes — external fragmentation. Strategies: First-Fit (first hole big enough), Best-Fit (smallest hole that fits), Worst-Fit (largest hole). Compaction can defragment but is expensive. This model is the historical predecessor of paging.",
      coreUnderstanding: "In contiguous allocation, each process gets a single contiguous block of physical memory. As processes come and go, free memory fragments into small non-contiguous holes — external fragmentation. Even if the total free memory is sufficient, no single hole may be large enough for a new process. Allocation strategies: First-Fit (allocate the first hole that's big enough — fast), Best-Fit (allocate the smallest hole that fits — minimizes waste, but creates tiny unusable holes), Worst-Fit (allocate the largest hole — leaves large remainders). Compaction (moving processes to create one large hole) fixes fragmentation but is expensive (copying memory, updating pointers). Paging solved this problem by eliminating external fragmentation.",
      howItWorks: "1. Memory is divided into two partitions: OS (low memory) and user processes (high memory).\n2. Each process gets a contiguous block. The OS tracks free holes in a free list.\n3. First-Fit: scan the free list, allocate the first hole >= requested size. Fast (first fit found).\n4. Best-Fit: scan all holes, allocate the smallest one >= requested size. Minimizes waste per allocation, but creates many tiny unusable holes.\n5. Worst-Fit: allocate the largest hole. Leaves large remainders (can fit other processes), but quickly reduces large holes.\n6. External fragmentation: total free memory suffices, but it's in small non-contiguous holes. No single hole is large enough.\n7. Compaction: move all processes to one end, creating one large free hole. Expensive (copy memory, update all pointers, stop the system).\n8. Internal fragmentation: if the allocated block is slightly larger than requested, the slack inside is wasted (rare in contiguous allocation, common in paging).",
      codeExamples: [{ lang: "text", code: "Contiguous Allocation Example:\n\nMemory layout (after some processes load/unload):\n  [OS][P1(50K)][free 20K][P2(30K)][free 10K][P3(40K)][free 30K]\n\nNew process P4 needs 25K:\n  First-Fit: allocate the 'free 30K' (first hole >= 25K)\n    Result: [free 5K] remains\n  Best-Fit:  allocate the 'free 30K' (smallest hole >= 25K)\n    Result: [free 5K] remains\n  Worst-Fit: allocate the 'free 30K' (largest hole)\n    Result: [free 5K] remains\n\nExternal Fragmentation:\n  Total free: 20K + 10K + 30K = 60K\n  P5 needs 40K -> NO single hole is big enough!\n  (60K > 40K, but fragmented into 20K + 10K + 30K)\n\nCompaction (fix):\n  Move P2, P3 to create one large hole:\n  [OS][P1(50K)][P2(30K)][P3(40K)][free 60K]\n  Now P5 (40K) fits. But compaction is expensive\n  (copying memory, updating pointers, stopping the system).\n\n// Paging eliminates this problem entirely.", output: "(contiguous allocation)", note: "Contiguous allocation: each process gets one block. External fragmentation (holes too small). Strategies: First-Fit (fast), Best-Fit (minimizes waste, creates tiny holes), Worst-Fit (large remainders). Compaction fixes but is expensive. Paging solves this." }],
      marginNotes: ["External fragmentation: total free memory suffices, but it's in small non-contiguous holes. No single hole is large enough for a new process. This is the main problem with contiguous allocation.", "First-Fit is usually the best strategy in practice — it's fast (scans from the start) and produces acceptable fragmentation. Best-Fit sounds good but creates many tiny unusable holes.", "Compaction (defragmentation) fixes external fragmentation by moving processes together, but it's expensive: the system must stop, copy memory, and update all pointers. This is why paging replaced contiguous allocation."],
      commonMistakes: ["Confusing external and internal fragmentation — external = free memory in small holes between allocated blocks (contiguous allocation, segmentation). Internal = allocated block larger than requested, wasting slack inside (paging).", "Thinking Best-Fit is always best — it minimizes waste per allocation, but creates many tiny unusable holes (external fragmentation). First-Fit is often better in practice."],
      relatedTopics: ["Internal & External Fragmentation", "Paging", "Memory Management"],
      externalLinks: [{ label: "Memory Allocation (Wiki)", url: "https://en.wikipedia.org/wiki/Memory_allocation" }],
      mcqs: [{ question: "What is external fragmentation?", options: ["Allocated memory is larger than needed, wasting the slack inside", "Free memory is split into small non-contiguous holes, none large enough for a new process", "Memory is physically damaged", "Too many processes are running"], answer: 1, explanations: ["That's internal fragmentation.", "Correct — external fragmentation: free memory is fragmented into small non-contiguous holes. Even though total free memory is sufficient, no single hole is large enough for a new process. Happens in contiguous allocation and segmentation. Fixed by compaction or paging.", "Physical damage is unrelated.", "Process count is not the issue."], difficulty: "medium" }] },
    { id: "fragmentation", title: "Internal & External Fragmentation", difficulty: "medium", definition: "External fragmentation: free memory is split into small holes too small to satisfy requests, even though total free memory suffices — happens in contiguous allocation and segmentation. Internal fragmentation: allocated memory is slightly larger than requested, wasting the slack inside the allocated block — happens in paging (fixed-size pages). Paging eliminates external but has internal; compaction fixes external but is costly.",
      coreUnderstanding: "Two types of fragmentation. External: free memory is split into small non-contiguous holes — total free memory suffices, but no single hole is large enough. Happens in contiguous allocation and segmentation. Fixed by compaction (expensive) or paging (which eliminates it). Internal: the allocated block is slightly larger than requested — the slack inside the block is wasted. Happens in paging (fixed-size pages: if a process needs 5KB and pages are 4KB, it gets 2 pages = 8KB, wasting 3KB). Paging eliminates external fragmentation but introduces internal (average waste = page_size/2 per allocation).",
      howItWorks: "1. External fragmentation: free memory in small holes between allocated blocks. Total free suffices, but no single hole fits. Happens in contiguous allocation and segmentation.\n2. Internal fragmentation: allocated block > requested. The slack inside is wasted. Happens in paging (fixed-size pages).\n3. Example: process needs 5KB. Pages are 4KB. Gets 2 pages (8KB). Wastes 3KB (internal fragmentation).\n4. Average internal fragmentation: page_size / 2 per allocation (on average, the last page is half full).\n5. External fix: compaction (move processes together, expensive) or paging (any page fits any frame, no external fragmentation).\n6. Internal fix: smaller pages (less waste per allocation, but more page table entries and more overhead). Typical page size: 4KB (balance between waste and overhead).\n7. Segmentation has external (variable-size segments create holes). Paging has internal (fixed-size pages waste slack). Combined systems have both.",
      codeExamples: [{ lang: "text", code: "Fragmentation Examples:\n\nExternal Fragmentation (contiguous allocation):\n  [OS][P1][free 20K][P2][free 10K][P3][free 30K]\n  Total free: 60K. New process needs 40K.\n  No single hole >= 40K! (20K + 10K + 30K = 60K)\n  Fix: compaction (move P2, P3) or paging.\n\nInternal Fragmentation (paging):\n  Page size: 4KB\n  Process needs: 5KB\n  Gets: 2 pages = 8KB\n  Wastes: 3KB (internal, inside the allocated pages)\n  Average waste per allocation: page_size / 2 = 2KB\n\nComparison:\n                    External    Internal\n  Contiguous         Yes          No\n  Paging             No           Yes\n  Segmentation       Yes          No\n  Paging+Segment     No           Yes\n\n// Paging eliminates external but has internal.\n// Internal is usually acceptable (average 2KB waste\n// per allocation with 4KB pages).\n// Smaller pages = less internal waste but more\n// page table overhead. 4KB is the sweet spot.", output: "(fragmentation examples)", note: "External: free memory in small holes (contiguous allocation, segmentation). Internal: allocated block larger than needed (paging). Paging eliminates external but has internal (avg waste = page_size/2). 4KB pages balance waste and overhead." }],
      marginNotes: ["External fragmentation = free memory in small holes between allocated blocks. Internal fragmentation = wasted slack inside allocated blocks. Paging eliminates external but introduces internal.", "Average internal fragmentation per allocation = page_size / 2 (the last page is on average half full). With 4KB pages, that's ~2KB wasted per allocation — usually acceptable.", "Smaller pages reduce internal fragmentation (less waste per allocation) but increase page table size and overhead. 4KB is the typical sweet spot, balancing waste and overhead."],
      commonMistakes: ["Confusing external and internal fragmentation — external = holes between allocated blocks (free but unusable). Internal = slack inside allocated blocks (allocated but unused).", "Thinking paging eliminates ALL fragmentation — it eliminates external but has internal (average page_size/2 waste per allocation)."],
      relatedTopics: ["Contiguous Memory Allocation", "Paging", "Segmentation"],
      externalLinks: [{ label: "Fragmentation (Wiki)", url: "https://en.wikipedia.org/wiki/Fragmentation_(computing)" }],
      mcqs: [{ question: "Which type of fragmentation does paging eliminate?", options: ["Internal", "External — any page fits any frame, no holes between allocations", "Both", "Neither"], answer: 1, explanations: ["Paging has internal fragmentation (slack in the last page).", "Correct — paging eliminates external fragmentation because any page can go in any frame. No holes between allocations. But paging introduces internal fragmentation: the last page is often partially used (average waste = page_size/2).", "Paging has internal.", "Paging fixes external, not both."], difficulty: "medium" }] },
    { id: "paging", title: "Paging", difficulty: "hard", definition: "Paging divides physical memory into fixed-size frames and logical memory into equal-size pages. The OS maps pages to frames via a page table — any page can go in any frame, so no external fragmentation. The CPU generates logical addresses; the MMU translates them to physical using the page table. Pages are typically 4KB. Paging is the foundation of modern virtual memory.",
      coreUnderstanding: "Paging divides physical memory into fixed-size frames and logical (virtual) memory into equal-size pages (typically 4KB). The OS maps pages to frames via a page table — any page can go in any frame, so there's no external fragmentation (no holes between allocations). The CPU generates virtual addresses; the MMU (Memory Management Unit) translates them to physical addresses using the page table. The translation: virtual address = page number + offset -> look up page number in page table -> get frame number -> physical address = frame number + offset. Paging is the foundation of modern virtual memory and provides isolation (each process has its own page table).",
      howItWorks: "1. Physical memory is divided into fixed-size frames (e.g., 4KB each).\n2. Virtual memory is divided into fixed-size pages (same size as frames, e.g., 4KB).\n3. Page table: maps page numbers to frame numbers. Each process has its own page table.\n4. Address translation: virtual address (page number, offset) -> page table lookup -> frame number -> physical address (frame number, offset).\n5. Example: virtual address 0x1A2B (page=1, offset=0xA2B). Page table: page 1 -> frame 5. Physical address = 5 * 4KB + 0xA2B.\n6. No external fragmentation: any page can go in any free frame (non-contiguous allocation).\n7. Internal fragmentation: if the last page is partially used, the slack is wasted (average page_size/2 per allocation).\n8. TLB: caches recent page table entries for fast translation (~99% hit rate).\n9. Valid/invalid bit: each page table entry has a valid bit (in RAM) or invalid bit (not mapped / on disk).",
      codeExamples: [{ lang: "text", code: "Paging Address Translation:\n\nVirtual Address: 0x1A2B (page size = 4KB = 0x1000)\n  Page number = 0x1A2B / 0x1000 = 1\n  Offset      = 0x1A2B % 0x1000 = 0xA2B\n\nPage Table (Process A):\n  Page 0 -> Frame 3\n  Page 1 -> Frame 5  (found!)\n  Page 2 -> Frame 1\n  Page 3 -> not in memory (on disk)\n\nPhysical Address = Frame 5 * 0x1000 + 0xA2B\n                 = 0x5A2B\n\nMemory Layout (non-contiguous!):\n  Frame 0: [OS]\n  Frame 1: Page 2 of Process A\n  Frame 2: [free]\n  Frame 3: Page 0 of Process A\n  Frame 4: Page 0 of Process B\n  Frame 5: Page 1 of Process A  <- our access\n  Frame 6: [free]\n  ...\n\n// Any page can go in any free frame.\n// No external fragmentation.\n// Internal: if process needs 5KB, gets 2 pages\n// (8KB), wasting 3KB.", output: "(paging translation)", note: "Paging: fixed-size pages (virtual) -> frames (physical) via page table. Any page fits any frame (no external fragmentation). MMU translates virtual to physical. TLB caches translations. Pages typically 4KB. Foundation of virtual memory." }],
      marginNotes: ["Paging eliminates external fragmentation because any page can go in any free frame — allocation is non-contiguous. The trade-off: internal fragmentation (average page_size/2 waste per allocation).", "The MMU (Memory Management Unit) is hardware that translates virtual to physical addresses using the page table. The TLB (Translation Lookaside Buffer) caches recent translations — without it, every memory access would require two memory accesses (page table + data).", "Each process has its own page table, providing isolation: Process A's page table only maps to its own frames. Process A can't access Process B's memory — the page table doesn't have those mappings."],
      commonMistakes: ["Confusing page (virtual) with frame (physical) — pages are in the process's virtual address space; frames are in physical RAM. The page table maps pages to frames.", "Forgetting the offset — the virtual address = page number + offset. The offset stays the same; only the page number is translated to a frame number."],
      relatedTopics: ["Page Tables & TLB", "Virtual Memory", "Internal & External Fragmentation"],
      externalLinks: [{ label: "Paging (Wiki)", url: "https://en.wikipedia.org/wiki/Paging" }],
      mcqs: [{ question: "What does the page table map?", options: ["Virtual addresses to physical addresses", "Page numbers to frame numbers", "Processes to memory", "Files to disk blocks"], answer: 1, explanations: ["Not full addresses — page numbers to frame numbers.", "Correct — the page table maps virtual page numbers to physical frame numbers. The offset within the page/frame stays the same. The MMU performs the lookup: virtual address (page, offset) -> page table -> (frame, offset) -> physical address.", "Not processes to memory.", "Not files to disk."], difficulty: "medium" }] },
    { id: "page-table", title: "Page Tables & TLB", difficulty: "hard", definition: "The page table maps logical page numbers to physical frame numbers. Every memory access requires a page table lookup, which would double access time. The TLB (Translation Lookaside Buffer) is a fast hardware cache of recent page table entries, hitting ~99% of the time. Multi-level page tables save memory for sparse address spaces. Inverted page tables map physical→logical to save space on 64-bit systems.",
      coreUnderstanding: "The page table maps virtual page numbers to physical frame numbers. Every memory access requires a page table lookup — without caching, this would double access time (one access for the page table, one for the data). The TLB (Translation Lookaside Buffer) is a fast hardware cache of recent page table entries, hitting ~99% of the time, making translation nearly free. For large address spaces (64-bit), a single-level page table would be enormous (millions of entries). Solutions: multi-level page tables (only create tables for used regions — saves memory for sparse address spaces) and inverted page tables (map physical frames to virtual pages — one entry per frame, not per page).",
      howItWorks: "1. Page table: an array where index = page number, value = frame number (plus valid/invalid bit, protection bits, dirty bit, etc.).\n2. TLB: hardware cache of recent page table entries. On each memory access: check TLB first. If hit (~99%), translation is instant. If miss, look up the page table (one extra memory access), then cache the entry in the TLB.\n3. Single-level page table: one entry per page. For a 32-bit address space with 4KB pages: 2^20 entries * 4 bytes = 4MB per process. Acceptable.\n4. For 64-bit: 2^52 entries * 8 bytes = enormous. Need multi-level.\n5. Multi-level page table: hierarchical. Outer table points to inner tables. Only create inner tables for used regions. Saves memory for sparse address spaces (most virtual addresses are unused).\n6. Inverted page table: one entry per physical frame (not per virtual page). Maps physical -> virtual. Much smaller (only need entries for physical frames, not virtual pages). Hash-based lookup. Used in PowerPC.\n7. x86-64 uses 4-level page tables (PGD -> PUD -> PMD -> PTE).",
      codeExamples: [{ lang: "text", code: "Page Table & TLB:\n\nSingle-Level Page Table (32-bit, 4KB pages):\n  Virtual address: 20-bit page number + 12-bit offset\n  Page table: 2^20 entries * 4 bytes = 4MB per process\n  Entry: [frame_number(20) | valid(1) | dirty(1) | ...]\n\nTLB (Translation Lookaside Buffer):\n  Hardware cache of recent page table entries\n  Hit rate: ~99% (temporal and spatial locality)\n  On hit: translation takes 0 extra memory accesses\n  On miss: 1 extra memory access (page table lookup)\n  TLB size: typically 64-1024 entries\n  Context switch: TLB must be flushed (different page table)\n    -> cold TLB -> many misses -> slow start\n  PCID (Process Context ID): avoids full TLB flush\n\nMulti-Level Page Table (x86-64, 4-level):\n  Level 1 (PGD): 512 entries -> PUD tables\n  Level 2 (PUD): 512 entries -> PMD tables\n  Level 3 (PMD): 512 entries -> PTE tables\n  Level 4 (PTE): 512 entries -> physical frames\n  Only create tables for used regions.\n  A sparse 64-bit address space uses little memory.\n\nInverted Page Table:\n  One entry per physical frame (not per virtual page)\n  Maps: physical frame -> virtual page + process ID\n  Lookup: hash the virtual page number\n  Much smaller for large address spaces\n  Used in PowerPC, IA-64", output: "(page table types)", note: "The page table maps page numbers to frame numbers. TLB caches entries (~99% hit rate). Multi-level tables save memory for sparse 64-bit address spaces. Inverted tables map physical->virtual (one entry per frame). x86-64 uses 4-level page tables." }],
      marginNotes: ["The TLB is crucial — without it, every memory access would require two memory accesses (one for the page table, one for the data). The TLB hits ~99% of the time due to temporal and spatial locality, making translation nearly free.", "Context switches flush the TLB (different page table) — the new process starts with a cold TLB, causing many misses and slow execution initially. PCID (Process Context ID) tags TLB entries with a process ID, avoiding full flushes.", "Multi-level page tables save memory for sparse address spaces (most of the 64-bit virtual address space is unused). Only tables for used regions are created. x86-64 uses 4-level page tables (PGD -> PUD -> PMD -> PTE)."],
      commonMistakes: ["Thinking the page table is in the CPU — it's in main memory. The TLB (hardware cache) is in the CPU. Each memory access checks the TLB first; on a miss, the page table (in RAM) is consulted.", "Forgetting that context switches flush the TLB — the new process has a different page table, so old TLB entries are invalid. This causes a cold-start performance penalty."],
      relatedTopics: ["Paging", "Virtual Memory", "Demand Paging & Page Faults"],
      externalLinks: [{ label: "Page Table (Wiki)", url: "https://en.wikipedia.org/wiki/Page_table" }],
      mcqs: [{ question: "What is the TLB (Translation Lookaside Buffer)?", options: ["A type of page table", "A fast hardware cache of recent page table entries, hitting ~99% of the time", "A disk cache", "A CPU register"], answer: 1, explanations: ["The TLB is not a page table — it caches page table entries.", "Correct — the TLB is a fast hardware cache inside the MMU that stores recent page table entries. Without it, every memory access would require an extra memory access for the page table lookup. The TLB hits ~99% of the time due to locality, making translation nearly free.", "It's not a disk cache.", "It's not a single register — it's a small associative cache."], difficulty: "medium" }] },
    { id: "segmentation", title: "Segmentation", difficulty: "medium", definition: "Segmentation divides a program's logical address space into variable-size segments (code, data, stack, heap) based on logical structure, not fixed sizes. Each segment has a base (start address) and limit (length). Segmentation reflects the programmer's view but suffers from external fragmentation. Most modern systems use paging (or a paging+segmentation combo) instead.",
      coreUnderstanding: "Segmentation divides a program's address space into variable-size segments based on logical structure: code segment, data segment, stack segment, heap segment. Each segment has a base (start address in physical memory) and a limit (length). The virtual address is (segment number, offset); the MMU adds the base to get the physical address and checks the offset < limit (protection). Segmentation reflects the programmer's view (logical divisions) and allows sharing (share the code segment between processes). The downside: variable-size segments cause external fragmentation (holes between segments). Most modern systems use paging instead (or a combination: segments are further divided into pages).",
      howItWorks: "1. A program is divided into logical segments: code, data, stack, heap, etc. Each segment has a name/number and a variable size.\n2. Segment table: maps segment numbers to (base, limit) pairs. base = start address in physical memory. limit = length.\n3. Address translation: virtual address (segment, offset) -> segment table -> (base, limit) -> physical address = base + offset.\n4. Protection: check offset < limit (prevents accessing beyond the segment).\n5. Sharing: multiple processes can share a segment (e.g., shared code library) by pointing their segment table entries to the same base.\n6. External fragmentation: variable-size segments create holes between them (like contiguous allocation). Compaction can fix it but is expensive.\n7. Segmentation + paging: each segment is further divided into pages. Combines logical structure (segments) with no external fragmentation (paging). Used in old x86 (segment:offset addressing).",
      codeExamples: [{ lang: "text", code: "Segmentation Example:\n\nSegment Table (Process A):\n  Segment 0 (code): base=1000, limit=500\n  Segment 1 (data): base=3000, limit=800\n  Segment 2 (stack): base=5000, limit=200\n  Segment 3 (heap): base=6000, limit=1000\n\nAddress Translation:\n  Virtual: (segment=1, offset=300)\n  -> Look up segment 1: base=3000, limit=800\n  -> Check: 300 < 800? Yes (protection)\n  -> Physical: 3000 + 300 = 3300\n\n  Virtual: (segment=1, offset=900)\n  -> Check: 900 < 800? NO! -> segmentation fault\n\nMemory Layout (variable sizes -> external frag):\n  [OS][Seg0(500)][free 200][Seg1(800)][free 100][Seg2(200)]...\n  External fragmentation: holes between segments\n\nSegmentation + Paging:\n  Each segment is divided into pages.\n  Virtual: (segment, page, offset)\n  -> Segment table -> page table -> physical frame\n  Combines logical structure (segments) with\n  no external fragmentation (paging)\n\n// Modern x86-64 mostly uses paging (flat model).\n// Segments are used mainly for protection\n// (code segment, data segment, etc.)", output: "(segmentation example)", note: "Segmentation: variable-size logical segments (code, data, stack, heap). Each has base+limit. Reflects programmer's view, allows sharing. Downside: external fragmentation (holes between segments). Modern systems use paging or segment+paging combo." }],
      marginNotes: ["Segmentation reflects the programmer's view (logical divisions: code, data, stack). Paging reflects the OS's view (fixed-size blocks). Segmentation allows sharing (share the code segment between processes), but causes external fragmentation.", "Most modern systems (x86-64) use paging, not segmentation. x86 segments are used mainly for protection (code segment, data segment) rather than memory management. The 'flat' memory model uses a single segment covering the entire address space.", "Segmentation + paging: each segment is divided into pages. Combines logical structure (segments) with no external fragmentation (paging). Used in old x86 but rare in modern systems."],
      commonMistakes: ["Confusing segmentation with paging — segmentation uses variable-size segments (logical divisions, external fragmentation). Paging uses fixed-size pages (no external fragmentation, internal fragmentation only).", "Thinking segmentation is used in modern systems — most use paging. x86-64 uses a flat memory model (single segment) with paging for memory management."],
      relatedTopics: ["Paging", "Internal & External Fragmentation", "Memory Management"],
      externalLinks: [{ label: "Segmentation (Wiki)", url: "https://en.wikipedia.org/wiki/Memory_segmentation" }],
      mcqs: [{ question: "What is the main disadvantage of segmentation?", options: ["Internal fragmentation", "External fragmentation — variable-size segments create holes between them", "It's too slow", "It doesn't provide isolation"], answer: 1, explanations: ["Segmentation has external, not internal fragmentation.", "Correct — segmentation uses variable-size segments. As segments load and unload, free memory fragments into holes between them (external fragmentation). This is the same problem as contiguous allocation. Paging (fixed-size pages) eliminates this.", "Speed is not the main issue.", "Segmentation does provide isolation (each segment has a base+limit)."], difficulty: "medium" }] },
    { id: "virtual-memory", title: "Virtual Memory", difficulty: "hard", definition: "Virtual memory gives each process the illusion of a large, contiguous, private address space, backed by physical RAM plus disk. Only the pages in active use need to be in RAM; the rest are swapped to disk (swap space). This lets programs be larger than physical memory and provides isolation between processes. Demand paging loads pages only when referenced, causing page faults when absent.",
      coreUnderstanding: "Virtual memory gives each process the illusion of a large, contiguous, private address space, backed by physical RAM + disk. Only the pages in active use need to be in RAM; the rest are swapped to disk (swap space/swap file). Benefits: (1) Programs can be larger than physical RAM (only active pages in memory). (2) Isolation: each process has its own page table, can't access others' memory. (3) Simplified programming: each process sees the same virtual address space (code at 0x400000, stack at 0x7FFF...). (4) Efficient memory use: only needed pages are loaded. Demand paging: pages are loaded only when accessed (lazy loading), causing page faults when the page isn't in RAM.",
      howItWorks: "1. Each process has a virtual address space (e.g., 48-bit on x86-64 = 256 TB). The OS divides it into pages (4KB).\n2. Page table: maps virtual pages to physical frames. Each entry has a valid bit: 1 = in RAM, 0 = on disk.\n3. Demand paging: when a process accesses a page with valid=0, a page fault occurs. The OS: finds the page on disk, loads it into a free frame, updates the page table (valid=1), and restarts the instruction.\n4. Page replacement: if no free frame, the OS evicts a page (FIFO, LRU, Clock). If the evicted page was modified (dirty bit), write it to disk first.\n5. Swap space: disk area for swapped-out pages. Slower than RAM but allows running more/larger programs.\n6. Isolation: each process has its own page table. Process A's page table only maps to its own frames — it can't access Process B's memory.\n7. TLB: caches page table entries for fast translation (~99% hit rate).",
      codeExamples: [{ lang: "bash", code: "# View virtual memory usage\nps aux | grep python\n# USER  PID  %CPU %MEM    VSZ   RSS  ...\n# user  1234  2.0  1.5  50000  12000 ...\n# VSZ = virtual size (50000 KB = ~50MB virtual)\n# RSS = resident set size (12000 KB = ~12MB in RAM)\n# Only 12MB of the 50MB virtual space is in RAM!\n\n# View swap usage\nswapon --show\n# NAME      TYPE  SIZE  USED  PRIO\n# /swapfile file  4G    256M  -2\n\n# View page faults\nps -o pid,min_flt,maj_flt 1234\n# PID   MIN_FLT  MAJ_FLT\n# 1234   1500     2\n# MIN_FLT = minor faults (page in RAM, just update table)\n# MAJ_FLT = major faults (page on disk, load from disk)\n\n# The process uses 50MB virtual but only 12MB physical.\n# The rest (38MB) is either unused or swapped to disk.\n# This is virtual memory in action.", output: "(virtual memory info)", note: "Virtual memory: each process sees a large private address space, backed by RAM + disk. Only active pages in RAM; rest swapped to disk. Demand paging loads on access (page faults). Isolation: each process has its own page table. Programs can exceed physical RAM." }],
      marginNotes: ["Virtual memory allows programs to be larger than physical RAM — only the active pages (working set) need to be in RAM. The rest are on disk (swap). This enables running multiple large programs simultaneously.", "Each process has its own page table, providing isolation. Process A can't access Process B's memory — the page table doesn't have those mappings. The MMU enforces this in hardware.", "RSS (Resident Set Size) vs VSZ (Virtual Size): RSS = pages in RAM. VSZ = total virtual address space. A process can have 500MB virtual but only 50MB resident — the rest is either unused or on disk."],
      commonMistakes: ["Thinking virtual memory is just RAM — it's RAM + disk (swap). Pages not in active use are swapped to disk. This lets programs exceed physical RAM.", "Confusing minor and major page faults — minor = page is in RAM (just needs table update, fast). Major = page is on disk (must load from disk, slow)."],
      relatedTopics: ["Demand Paging & Page Faults", "Page Replacement Algorithms", "Paging"],
      externalLinks: [{ label: "Virtual Memory (Wiki)", url: "https://en.wikipedia.org/wiki/Virtual_memory" }],
      mcqs: [{ question: "What is the main benefit of virtual memory?", options: ["It makes RAM faster", "It allows programs to be larger than physical RAM and provides isolation between processes", "It compresses memory", "It encrypts memory"], answer: 1, explanations: ["Speed is not the benefit — disk is slower than RAM.", "Correct — virtual memory gives each process a large private address space backed by RAM + disk. Only active pages need to be in RAM; the rest are on disk (swap). This lets programs exceed physical RAM and provides isolation (each process has its own page table).", "It doesn't compress.", "It doesn't encrypt."], difficulty: "easy" }] },
    { id: "demand-paging", title: "Demand Paging & Page Faults", difficulty: "hard", definition: "Demand paging loads pages into memory only when they are actually accessed (lazy loading). When a process accesses a page not in RAM, a page fault occurs: the OS traps, finds the page on disk, loads it into a free frame, updates the page table, and restarts the instruction. Page faults are expensive (disk I/O), so the OS tries to minimize them via good replacement policies and prefetching.",
      coreUnderstanding: "Demand paging loads pages into RAM only when they're actually accessed (lazy loading). When a process accesses a page not in RAM (valid bit = 0), a page fault occurs: the CPU traps to the OS, the OS finds the page on disk, loads it into a free frame, updates the page table (valid = 1), and restarts the instruction. The process is unaware (except for the delay). Page faults are expensive (disk I/O — ~100,000x slower than RAM), so the OS minimizes them via good replacement policies (LRU, Clock) and prefetching (load nearby pages speculatively, exploiting spatial locality). The working set (pages in active use) should fit in RAM; if not, thrashing occurs.",
      howItWorks: "1. Demand paging: pages start on disk (valid bit = 0). Loaded only when accessed.\n2. Page fault: CPU accesses virtual address -> page table: valid bit = 0 -> page fault exception.\n3. OS page fault handler: (a) find the page on disk (from swap space or the executable file). (b) find a free frame (or evict a page if none free). (c) load the page from disk into the frame (disk I/O, slow). (d) update the page table: frame number, valid = 1. (e) restart the faulting instruction.\n4. Cost: ~1-10 ms for a page fault (disk I/O). Compare: ~100ns for a memory access. Page faults are 10,000-100,000x slower.\n5. Minor fault: page is in RAM (e.g., shared page, zero-fill). Fast (no disk I/O).\n6. Major fault: page is on disk. Slow (disk I/O).\n7. Prefetching: when a page is accessed, also load nearby pages (spatial locality). Reduces future faults.\n8. Working set: the set of pages a process is actively using. Should fit in RAM for good performance.",
      codeExamples: [{ lang: "text", code: "Demand Paging & Page Fault Flow:\n\n1. Process accesses virtual address (page 5, offset 200)\n2. MMU looks up page 5 in page table\n3. Valid bit = 0 (page not in RAM)\n   -> PAGE FAULT!\n\n4. CPU traps to OS page fault handler:\n   a. Check: is this a valid address? (in the process's\n      address space?) If not -> SIGSEGV (segfault).\n   b. Find the page on disk (swap space or executable file)\n   c. Find a free frame:\n      - If free frame exists: use it\n      - If no free frame: evict a page (page replacement)\n        * If evicted page is dirty (modified): write to disk\n        * If clean: just discard\n   d. Load page from disk into the frame (DISK I/O: ~1-10ms)\n   e. Update page table: page 5 -> frame 12, valid = 1\n   f. Restart the faulting instruction (now it succeeds)\n\n5. Process continues, unaware (except for the delay)\n\nPerformance:\n  Memory access:    ~100 nanoseconds\n  Page fault:       ~1-10 milliseconds (10,000-100,000x slower)\n  \n  If working set fits in RAM: ~0 page faults (fast)\n  If working set > RAM: many faults -> thrashing (very slow)", output: "(page fault flow)", note: "Demand paging: pages loaded only when accessed. Page fault: OS traps, loads from disk, updates page table, restarts. Expensive (~1-10ms, 10,000-100,000x slower than RAM). Minimize via replacement policies and prefetching." }],
      marginNotes: ["Page faults are extremely expensive (~1-10ms) compared to memory access (~100ns) — 10,000-100,000x slower. The OS minimizes them via good replacement policies (LRU, Clock) and prefetching (load nearby pages).", "Minor fault: the page is already in RAM (e.g., shared page, zero-fill on demand). No disk I/O — fast. Major fault: the page is on disk. Requires disk I/O — slow.", "The working set (pages in active use) should fit in RAM. If it doesn't, the process constantly page-faults (thrashing) — spending more time swapping than computing. The OS detects this and may swap out the entire process."],
      commonMistakes: ["Thinking demand paging loads the entire program at start — it doesn't. Pages are loaded lazily (on first access). This saves memory and startup time for pages never used.", "Forgetting that page faults are extremely expensive — a single page fault takes ~1-10ms (disk I/O). Programs with poor locality (random access to large data) can be 100x slower due to constant page faults."],
      relatedTopics: ["Virtual Memory", "Page Replacement Algorithms", "Thrashing"],
      externalLinks: [{ label: "Demand Paging (Wiki)", url: "https://en.wikipedia.org/wiki/Demand_paging" }],
      mcqs: [{ question: "What happens during a page fault?", options: ["The program crashes immediately", "The OS traps, loads the page from disk into a free frame, updates the page table, and restarts the instruction", "The CPU skips the instruction", "The OS allocates more RAM"], answer: 1, explanations: ["The program doesn't crash (for valid addresses).", "Correct — on a page fault, the CPU traps to the OS. The OS finds the page on disk, loads it into a free frame (evicting a page if necessary), updates the page table, and restarts the faulting instruction. This is transparent to the process (except for the delay).", "The instruction is retried, not skipped.", "The OS doesn't add physical RAM — it uses disk (swap)."], difficulty: "medium" }] },
    { id: "page-replacement", title: "Page Replacement Algorithms", difficulty: "hard", definition: "When a page fault occurs and no free frame is available, the OS must evict a page. FIFO evicts the oldest page. LRU (Least Recently Used) evicts the page not used for the longest time — good but expensive to implement. Optimal replaces the page not used for the longest future time — theoretically best but impossible (can't know the future). Clock (second-chance) approximates LRU cheaply. Belady's anomaly: FIFO can fault more with more frames.",
      coreUnderstanding: "When a page fault occurs and no free frame is available, the OS must evict a page to make room. The goal: evict the page least likely to be needed soon. Algorithms: (1) FIFO — evict the oldest page (first in). Simple but can evict frequently used pages and suffers from Belady's anomaly (more frames can cause MORE faults). (2) LRU — evict the page not used for the longest time. Excellent but expensive to implement (needs timestamp/stack per page). (3) Optimal — evict the page not used for the longest future time. Theoretically best but impossible (can't know the future). Used as a benchmark. (4) Clock (second-chance) — approximation of LRU using a reference bit. When a page is accessed, set the bit. When evicting, give pages with the bit set a 'second chance' (clear the bit, skip). Cheap and close to LRU in practice.",
      howItWorks: "1. FIFO: evict the page that was loaded first (oldest). Simple (queue). But: may evict a frequently used page (e.g., code page). Suffers from Belady's anomaly.\n2. LRU: evict the page not accessed for the longest time. Excellent (follows locality). But: expensive to track (need timestamp on every access, or a stack). Hardware support (reference bit) helps.\n3. Optimal (OPT): evict the page not used for the longest future time. Provably minimal faults. But: impossible (can't know the future). Used as a benchmark to evaluate other algorithms.\n4. Clock (second-chance): approximation of LRU. Each page has a reference bit (set by hardware on access). A clock hand sweeps through pages. When evicting: if the reference bit is 1, clear it and skip (second chance). If 0, evict it. Cheap and close to LRU.\n5. Belady's anomaly: with FIFO, adding more frames can INCREASE page faults (counterintuitive). LRU and Optimal don't have this anomaly.\n6. Dirty bit: if the evicted page was modified (dirty bit = 1), write it to disk first. If clean, just discard.",
      codeExamples: [{ lang: "text", code: "Page Replacement Example:\n\nReference string: 1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5\n3 frames available\n\nFIFO:\n  Load 1: [1, -, -] fault\n  Load 2: [1, 2, -] fault\n  Load 3: [1, 2, 3] fault\n  Load 4: [4, 2, 3] fault (evict 1, oldest)\n  Load 1: [4, 1, 3] fault (evict 2)\n  Load 2: [4, 1, 2] fault (evict 3)\n  Load 5: [5, 1, 2] fault (evict 4)\n  Load 1: hit! (1 is in memory)\n  Load 2: hit!\n  Load 3: [5, 3, 2] fault (evict 1)\n  Load 4: [5, 3, 4] fault (evict 2)\n  Load 5: hit!\n  Total: 10 faults\n\nLRU:\n  (evict the least recently used)\n  Load 1: [1] fault\n  Load 2: [1,2] fault\n  Load 3: [1,2,3] fault\n  Load 4: [4,2,3] fault (evict 1, LRU)\n  Load 1: [4,1,3] fault (evict 2, LRU)\n  ...\n  Total: ~9 faults (better than FIFO)\n\nOptimal (benchmark):\n  Evict the page not used for the longest future\n  Total: ~7 faults (best possible)\n\nClock (second-chance):\n  Use reference bits. Give pages with bit=1\n  a second chance (clear bit, skip).\n  Close to LRU, much cheaper to implement.", output: "(page replacement)", note: "Page replacement: FIFO (oldest, simple, Belady's anomaly), LRU (least recently used, excellent but expensive), Optimal (benchmark, impossible), Clock (second-chance, approximates LRU cheaply). Dirty pages are written to disk before eviction." }],
      marginNotes: ["LRU is the best practical algorithm (follows locality) but is expensive to implement exactly (need to track access time per page). Clock (second-chance) is a cheap approximation that's close to LRU in practice.", "Belady's anomaly: with FIFO, adding more frames can INCREASE page faults (counterintuitive). LRU and Optimal don't have this anomaly (they're 'stack algorithms' — more frames never hurts).", "Optimal is the theoretical best (evict the page not used for the longest future time) but is impossible to implement (can't predict the future). It's used as a benchmark to evaluate practical algorithms."],
      commonMistakes: ["Thinking more frames always reduce faults — with FIFO (Belady's anomaly), more frames can cause MORE faults. LRU and Optimal don't have this problem.", "Forgetting to write dirty pages to disk — if the evicted page was modified (dirty bit = 1), the OS must write it to disk before discarding. Clean pages can be discarded directly."],
      relatedTopics: ["Demand Paging & Page Faults", "Virtual Memory", "Thrashing"],
      externalLinks: [{ label: "Page Replacement (Wiki)", url: "https://en.wikipedia.org/wiki/Page_replacement_algorithm" }],
      mcqs: [{ question: "Which page replacement algorithm suffers from Belady's anomaly?", options: ["LRU", "Optimal", "FIFO — adding more frames can cause MORE page faults", "Clock"], answer: 2, explanations: ["LRU doesn't have Belady's anomaly (it's a stack algorithm).", "Optimal doesn't have Belady's anomaly.", "Correct — FIFO suffers from Belady's anomaly: adding more frames can INCREASE page faults (counterintuitive). LRU and Optimal are 'stack algorithms' — more frames never hurts.", "Clock doesn't have Belady's anomaly."], difficulty: "hard" }] },
    { id: "thrashing", title: "Thrashing", difficulty: "hard", definition: "Thrashing occurs when a process spends more time paging (swapping pages in/out) than executing — the system collapses into near-zero useful work. It happens when the working set (pages actively used) exceeds available physical memory. The OS detects thrashing via high page-fault rates and responds by reducing the degree of multiprogramming (swapping out entire processes) or the working-set model to control memory allocation.",
      coreUnderstanding: "Thrashing occurs when a process spends more time paging (swapping pages in/out of disk) than executing — the system collapses into near-zero useful work. It happens when the total working set (pages in active use across all processes) exceeds available physical memory. Each process keeps faulting, evicting pages that other processes need, which then fault — a cascade of page faults. The OS detects thrashing via high page-fault rates and responds by reducing the degree of multiprogramming (swapping out entire processes to free memory) or using the working-set model (track each process's working set and ensure it fits in RAM). Prevention: don't load more processes than memory can hold.",
      howItWorks: "1. Working set: the set of pages a process is actively using (recently accessed). This must be in RAM for good performance.\n2. Thrashing trigger: if the sum of all processes' working sets > physical RAM, each process keeps faulting.\n3. Cascade: Process A faults, evicts Process B's page. B faults, evicts C's page. C faults, evicts A's page. Everyone is paging, nobody is computing.\n4. Detection: the OS monitors the page-fault rate. If it exceeds a threshold, thrashing is occurring.\n5. Response: reduce the degree of multiprogramming — swap out entire processes (suspend them to disk) until the remaining processes' working sets fit in RAM.\n6. Working-set model: the OS tracks each process's working set (pages used in the last T seconds). Allocates enough frames for each working set. If total > RAM, swap out a process.\n7. Page-fault frequency (PFF): dynamically adjust the number of frames per process based on its fault rate. High fault rate -> give more frames. Low -> take frames away.",
      codeExamples: [{ lang: "text", code: "Thrashing Scenario:\n\nPhysical RAM: 100 frames\n\nProcesses and their working sets:\n  P1: 30 pages (working set)\n  P2: 30 pages\n  P3: 30 pages\n  P4: 30 pages\n  Total: 120 pages > 100 frames -> THRASHING!\n\nWhat happens:\n  P1 accesses a page -> fault (not in RAM)\n  OS evicts a page from P2 to make room\n  P2 accesses a page -> fault (just evicted!)\n  OS evicts a page from P3\n  P3 accesses a page -> fault\n  ...\n  Cascade: everyone faults, nobody computes.\n  CPU utilization drops to near 0.\n  Disk is 100% busy swapping.\n\nDetection:\n  - High page-fault rate (> threshold)\n  - Low CPU utilization\n  - High disk I/O (swap)\n\nFix: reduce degree of multiprogramming\n  Swap out P4 entirely (suspend to disk)\n  Now P1+P2+P3 = 90 pages < 100 frames\n  Working sets fit -> no thrashing\n  P4 runs later when memory is available\n\nWorking-Set Model:\n  Track each process's working set (pages\n  used in the last T seconds).\n  If sum > RAM, swap out a process.\n  Ensures remaining processes have enough\n  memory for their working sets.", output: "(thrashing scenario)", note: "Thrashing: processes spend more time paging than computing. Happens when total working sets > physical RAM. Cascade of page faults. Detection: high fault rate, low CPU. Fix: reduce multiprogramming (swap out processes) or working-set model." }],
      marginNotes: ["Thrashing is a death spiral: processes keep evicting each other's pages, causing a cascade of page faults. CPU utilization drops to near 0, disk is 100% busy swapping. The system appears frozen.", "The working set model prevents thrashing: track each process's working set (pages used in the last T seconds). If the total exceeds RAM, swap out processes until the remaining working sets fit.", "The degree of multiprogramming (number of processes in memory) should be limited by available RAM. Loading too many processes leads to thrashing. The OS should detect high fault rates and reduce multiprogramming."],
      commonMistakes: ["Thinking more processes = more throughput — beyond a point, adding processes causes thrashing (each process doesn't have enough memory for its working set). Throughput crashes.", "Ignoring thrashing symptoms — a frozen system with 100% disk I/O and ~0% CPU is likely thrashing. The fix is to reduce the number of running processes, not add more."],
      relatedTopics: ["Demand Paging & Page Faults", "Virtual Memory", "Page Replacement Algorithms"],
      externalLinks: [{ label: "Thrashing (Wiki)", url: "https://en.wikipedia.org/wiki/Thrashing_(computer_science)" }],
      mcqs: [{ question: "What causes thrashing?", options: ["Too much RAM", "The total working set (pages in active use) exceeds physical memory — processes keep evicting each other's pages", "The CPU is too slow", "The disk is too fast"], answer: 1, explanations: ["Too much RAM prevents thrashing.", "Correct — thrashing occurs when the sum of all processes' working sets exceeds physical RAM. Each process keeps faulting, evicting pages other processes need. A cascade of page faults leads to near-zero useful work. Fix: reduce multiprogramming (swap out processes).", "CPU speed is not the cause.", "Disk speed is not the cause (disk being 100% busy is a symptom, not a cause)."], difficulty: "medium" }] },
    { id: "file-system", title: "File Systems", difficulty: "medium", definition: "A file system organizes data on storage into files and directories, providing naming, access control, and navigation. It tracks which disk blocks belong to which file, free space, and metadata (size, timestamps, permissions). Common types: ext4 (Linux), NTFS (Windows), APFS (macOS), FAT (legacy/portable). The file system is the OS's persistent data management layer.",
      coreUnderstanding: "A file system organizes data on persistent storage (disk, SSD) into files and directories. It provides naming (human-readable names), access control (permissions), and navigation (directories/paths). The file system tracks: which disk blocks belong to which file, free space (bitmap or free list), and metadata (size, timestamps, permissions, ownership). Common types: ext4 (Linux, journaling), NTFS (Windows, journaling, ACLs), APFS (macOS, SSD-optimized, snapshots), FAT32/exFAT (legacy, portable, simple). The file system is the OS's persistent data management layer — without it, disk is just a raw block device.",
      howItWorks: "1. File: a named collection of related data on disk. Has metadata (inode in ext4, MFT entry in NTFS): size, timestamps, permissions, block list.\n2. Directory: a special file containing a list of (filename, file pointer) entries.\n3. Block allocation: the file system tracks which disk blocks belong to which file (contiguous, linked, indexed, or extents).\n4. Free space management: bitmap (1 bit per block — 1=free, 0=used) or free list (linked list of free blocks).\n5. Metadata: stored in an inode (ext4) or MFT entry (NTFS). Contains: size, timestamps, permissions, block pointers.\n6. Journaling (ext4, NTFS): before modifying the file system, write a log entry. If a crash occurs, replay the log to restore consistency. Prevents corruption.\n7. Common operations: open (load metadata), read/write (access data blocks), close (flush metadata), create/delete, mkdir/rmdir, rename.",
      codeExamples: [{ lang: "bash", code: "# View file system info\nls -l file.txt\n# -rw-r--r-- 1 user group 1234 Jul 31 14:30 file.txt\n# permissions | links | owner | group | size | date | name\n\n# View inode (metadata) of a file\nstat file.txt\n# File: file.txt\n# Size: 1234        Blocks: 8        IO Block: 4096\n# Inode: 1234567    Links: 1\n# Access: (0644/-rw-r--r--)  Uid: (1000/user)\n# Modify: 2024-07-31 14:30:00\n# Change: 2024-07-31 14:30:00\n# Birth:  2024-07-31 14:25:00\n\n# View file system type\n df -T /\n# Filesystem  Type  Size  Used  Avail  Use%\n# /dev/sda1   ext4  100G  45G   55G    45%\n\n# Common file systems:\n# ext4:  Linux default (journaling)\n# NTFS:  Windows (journaling, ACLs)\n# APFS:  macOS (SSD-optimized, snapshots)\n# FAT32/exFAT: portable (USB drives, cameras)\n# ZFS:  enterprise (checksums, snapshots)\n# Btrfs: Linux (copy-on-write, snapshots)", output: "(file system info)", note: "A file system organizes disk data into files and directories. Tracks blocks, free space, metadata (inode: size, timestamps, permissions). Journaling (ext4, NTFS) prevents corruption. Types: ext4 (Linux), NTFS (Windows), APFS (macOS), FAT (portable)." }],
      marginNotes: ["Journaling (ext4, NTFS, APFS): before modifying the file system, write a log entry. If a crash occurs, replay the log to restore consistency. Prevents the file system from being left in a corrupted state.", "The inode (ext4) or MFT entry (NTFS) stores file metadata: size, timestamps, permissions, block pointers. The filename is stored in the directory, not the inode — this allows hard links (multiple names for the same inode).", "FAT32/exFAT is simple and portable (USB drives, cameras) but lacks journaling (corruption risk on crash), permissions, and large file support (FAT32 max file = 4GB). Use ext4/NTFS/APFS for system drives."],
      commonMistakes: ["Thinking the filename is stored in the file's metadata — it's not. The filename is stored in the directory entry. The inode has no name. This is why hard links work (multiple directory entries pointing to the same inode).", "Using non-journaling file systems (FAT32) for important data — a crash can corrupt the file system. Use journaling file systems (ext4, NTFS, APFS) for reliability."],
      relatedTopics: ["File Allocation Methods", "Directory Structure", "Disk Scheduling Algorithms"],
      externalLinks: [{ label: "File System (Wiki)", url: "https://en.wikipedia.org/wiki/File_system" }],
      mcqs: [{ question: "What is journaling in a file system?", options: ["Compressing files", "Writing a log entry before modifying the file system, so crashes can be recovered by replaying the log", "Encrypting files", "Defragmenting the disk"], answer: 1, explanations: ["Compression is unrelated.", "Correct — journaling (ext4, NTFS, APFS) writes a log entry before modifying the file system. If a crash occurs, the OS replays the log on restart to restore consistency. This prevents file system corruption.", "Encryption is unrelated.", "Defragmentation is unrelated."], difficulty: "medium" }] },
    { id: "file-allocation", title: "File Allocation Methods", difficulty: "medium", definition: "Methods for mapping file blocks to disk blocks: Contiguous allocation (each file gets consecutive blocks — fast sequential access, suffers fragmentation), Linked allocation (each block points to the next — no fragmentation, slow random access, pointer overhead), Indexed allocation (an index block lists all the file's blocks — fast random access, index overhead). Most modern file systems use variants of indexed allocation (ext4 uses extents).",
      coreUnderstanding: "File allocation methods determine how file data is mapped to disk blocks. Three approaches: (1) Contiguous allocation — each file gets consecutive blocks. Fast sequential access (just read consecutive blocks) and random access (calculate: block = start + offset). Suffers from external fragmentation (holes between files) and file size must be known in advance. (2) Linked allocation — each block contains data + a pointer to the next block. No external fragmentation (blocks can be anywhere). But random access is slow (must traverse the chain from the start) and pointers waste space. (3) Indexed allocation — an index block (or inode) lists all the file's blocks. Fast random access (look up in index) and no external fragmentation. Index overhead. Most modern file systems use indexed allocation with extents (contiguous runs of blocks, reducing index entries).",
      howItWorks: "1. Contiguous: file = starting block + length. Read block N: start + N. Fast sequential and random. Problems: external fragmentation (files must be contiguous), file can't grow easily (need to move if adjacent blocks are used).\n2. Linked: each block = data + next block pointer. File = first block pointer. Read block N: traverse from start, following pointers (O(N) — slow random access). No external fragmentation (blocks anywhere). Problems: pointer overhead (4 bytes per block), can't easily seek, pointer corruption loses the rest.\n3. Indexed: inode/index block = array of block numbers. Read block N: look up index[N]. O(1) random access. No external fragmentation. Problem: index size (large files need multi-level indexes — direct, single indirect, double indirect, triple indirect in ext4).\n4. Extents (ext4, modern): instead of listing every block, store contiguous runs: (start, length). A 1GB file might need only 1 extent instead of 262,144 block pointers. Much more efficient.\n5. FAT (File Allocation Table): linked allocation with the table stored separately (in the FAT). Reading the FAT is fast (cached), giving near-indexed performance.",
      codeExamples: [{ lang: "text", code: "File Allocation Methods:\n\n1. Contiguous Allocation:\n   File A: start=10, length=5  (blocks 10-14)\n   File B: start=20, length=3  (blocks 20-22)\n   \n   Disk: [..][A A A A A][free][B B B][free][..]\n   \n   Read block 3 of A: block 10+3 = 13 (O(1))\n   Problem: A can't grow (no adjacent free space)\n   Problem: external fragmentation (holes)\n\n2. Linked Allocation:\n   File A: first block = 10\n   Block 10: [data | next=25]\n   Block 25: [data | next=7]\n   Block  7: [data | next=NULL]\n   \n   Disk: [..][A][..][A][..][A][..]\n   (blocks can be anywhere)\n   \n   Read block 2 of A: traverse 10->25 (O(N))\n   No external fragmentation\n   Problem: slow random access, pointer overhead\n\n3. Indexed Allocation (ext4 inode):\n   Inode: [block 10][block 25][block 7][...]\n   \n   Read block 2 of A: look up index[2] = 7 (O(1))\n   No external fragmentation\n   Problem: index size for large files\n   Solution: multi-level (direct, indirect,\n   double-indirect, triple-indirect)\n   \n4. Extents (ext4, modern):\n   Inode: [extent: start=10, len=5]\n   (one entry for 5 consecutive blocks)\n   \n   1GB file: 1 extent instead of 262,144\n   block pointers. Much more efficient.", output: "(allocation methods)", note: "Contiguous (fast, but fragmentation, can't grow). Linked (no fragmentation, slow random access). Indexed (fast random access, index overhead — ext4 uses multi-level). Extents (modern: contiguous runs, much more efficient for large files)." }],
      marginNotes: ["Extents (ext4, modern file systems): instead of listing every block, store contiguous runs (start, length). A 1GB file might need only 1 extent instead of 262,144 block pointers. Much more efficient for large files.", "Contiguous allocation is like an array: fast random access (start + offset) but can't grow and suffers from fragmentation. Linked is like a linked list: no fragmentation but slow random access. Indexed is like a hash table: fast random access, no fragmentation.", "FAT (File Allocation Table) is linked allocation with the links stored in a separate table (the FAT) that's cached in RAM. This gives near-indexed performance for random access while maintaining linked allocation's lack of fragmentation."],
      commonMistakes: ["Confusing contiguous allocation (external fragmentation) with indexed (no external fragmentation). Contiguous = files must be consecutive; indexed = blocks anywhere, index lists them.", "Thinking linked allocation has fast random access — it doesn't. You must traverse the chain from the start to reach block N. This is O(N), making it unsuitable for random access."],
      relatedTopics: ["File Systems", "Directory Structure", "Internal & External Fragmentation"],
      externalLinks: [{ label: "File Allocation (Wiki)", url: "https://en.wikipedia.org/wiki/File_allocation" }],
      mcqs: [{ question: "Which file allocation method provides the fastest random access?", options: ["Linked", "Contiguous (start + offset, O(1))", "Indexed (look up in index, O(1))", "Sequential"], answer: 1, explanations: ["Linked is O(N) for random access — must traverse the chain.", "Correct — contiguous allocation: block N = start + N. O(1) random access. But suffers from external fragmentation and files can't grow easily. Indexed allocation (ext4) also provides O(1) random access via the index/inode.", "Indexed also provides O(1), but contiguous is the traditional answer. Both are fast.", "Sequential is a pattern, not an allocation method."], difficulty: "medium" }] },
    { id: "directory-structure", title: "Directory Structure", difficulty: "easy", definition: "Directories organize files into a hierarchy (tree) for naming and navigation. Single-level (flat) is too simple for many files. Two-level (per-user) is better but flat within each. Tree-structured directories (the standard) allow arbitrary nesting with absolute and relative paths. Acyclic-graph directories allow shared subdirectories (links/symlinks) but complicate deletion. The path uniquely identifies a file.",
      coreUnderstanding: "Directories organize files into a hierarchy for naming and navigation. Evolution: (1) Single-level (flat) — all files in one directory. Too simple for many files (name collisions). (2) Two-level — each user gets their own directory. Better but flat within each. (3) Tree-structured (the standard) — arbitrary nesting. Absolute paths (/home/user/file.txt) and relative paths (../file.txt). Each file has a unique path. (4) Acyclic-graph — allows shared subdirectories (hard links, symlinks). Sharing is useful but complicates deletion (reference counting). Modern file systems use tree-structured directories with optional links (symlinks, hard links).",
      howItWorks: "1. A directory is a special file containing a list of entries: (filename, file pointer/inode).\n2. Tree structure: the root directory (/) contains subdirectories, which contain subdirectories, etc. Each file has a unique path (absolute or relative).\n3. Absolute path: /home/user/documents/file.txt — from the root.\n4. Relative path: documents/file.txt or ../images/photo.png — from the current directory.\n5. Special entries: . (current directory), .. (parent directory).\n6. Hard link: a directory entry pointing to the same inode. Two names for the same file. Deleting one doesn't delete the file (reference count). Can't cross file systems or link to directories.\n7. Symbolic link (symlink): a special file containing the path to another file. Like a shortcut. Can cross file systems and link to directories. If the target is deleted, the symlink becomes dangling.\n8. Operations: mkdir, rmdir, readdir (list entries), rename (move).",
      codeExamples: [{ lang: "bash", code: "# Tree-structured directories\nls -la /\n# drwxr-xr-x  bin\n# drwxr-xr-x  home\n# drwxr-xr-x  usr\n# ...\n\n# Absolute path (from root)\ncat /home/user/file.txt\n\n# Relative path (from current directory)\ncat documents/file.txt\ncat ../images/photo.png  # .. = parent directory\n\n# Special entries: . and ..\nls -la\n# drwxr-xr-x  .   (current directory)\n# drwxr-xr-x  ..  (parent directory)\n\n# Hard link: two names for the same inode\nln file.txt hardlink.txt\nls -li  # -i shows inode numbers\n# 1234567 file.txt\n# 1234567 hardlink.txt  (same inode!)\nrm file.txt  # file still exists (hardlink references it)\n\n# Symbolic link (symlink): a file containing a path\nln -s /home/user/file.txt symlink.txt\nls -la symlink.txt\n# symlink.txt -> /home/user/file.txt\nrm /home/user/file.txt  # symlink now dangles!\ncat symlink.txt  # No such file or directory\n\n# Directory operations\nmkdir new_dir\nrmdir empty_dir  # only works if empty\nrm -r non_empty_dir  # recursive delete", output: "(directory operations)", note: "Directories are tree-structured (arbitrary nesting). Absolute (/path/to/file) and relative (../file) paths. Hard links: same inode, can't dangle. Symlinks: path to another file, can dangle. Each file has a unique path." }],
      marginNotes: ["Hard links: two directory entries pointing to the same inode (same file). Deleting one doesn't delete the file (reference count > 0). Can't cross file systems or link to directories (prevents cycles).", "Symlinks (symbolic links): a special file containing the path to another file. Like a shortcut. Can cross file systems and link to directories. If the target is deleted, the symlink dangles (points to nothing).", "The tree structure ensures every file has a unique path. Acyclic-graph structures (with hard links/symlinks) allow sharing but complicate deletion (reference counting for hard links, dangling for symlinks)."],
      commonMistakes: ["Confusing hard links with symlinks — hard links point to the same inode (same data, can't dangle). Symlinks point to a path (can dangle if the target is deleted).", "Thinking rmdir can delete non-empty directories — it can't. Use rm -r for recursive deletion."],
      relatedTopics: ["File Systems", "File Allocation Methods", "Internal & External Fragmentation"],
      externalLinks: [{ label: "Directory (Wiki)", url: "https://en.wikipedia.org/wiki/Directory_(computing)" }],
      mcqs: [{ question: "What is the difference between a hard link and a symbolic link (symlink)?", options: ["They are the same", "Hard link points to the same inode (same data, can't dangle); symlink points to a path (can dangle if target is deleted)", "Hard links are faster", "Symlinks are deprecated"], answer: 1, explanations: ["They are different.", "Correct — a hard link is a directory entry pointing to the same inode (same data). Deleting one hard link doesn't delete the file (reference count). Can't cross file systems. A symlink is a file containing a path to another file. Can cross file systems. If the target is deleted, the symlink dangles (points to nothing).", "Speed is not the key difference.", "Symlinks are not deprecated."], difficulty: "medium" }] },
    { id: "disk-scheduling", title: "Disk Scheduling Algorithms", difficulty: "medium", definition: "Disk I/O is slow because of physical seek time (moving the head). Disk scheduling reorders requests to minimize head movement. FCFS services in arrival order (fair but slow). SSTF (Shortest Seek Time First) picks the nearest request (can starve far requests). SCAN (elevator) sweeps back and forth. C-SCAN always moves one direction, jumping back. LOOK/C-LOOK reverse at the last request, not the disk edge.",
      coreUnderstanding: "Disk I/O is slow because of physical seek time (moving the disk head to the right track). Disk scheduling reorders I/O requests to minimize head movement, improving throughput. Algorithms: (1) FCFS — service in arrival order. Fair but slow (head jumps around). (2) SSTF (Shortest Seek Time First) — service the nearest request. Good throughput but can starve far requests. (3) SCAN (elevator) — sweep back and forth across the disk. When the head reaches one end, reverse direction. Fair and efficient. (4) C-SCAN (Circular SCAN) — always move in one direction (e.g., outward), then jump back to the start. More uniform wait times. (5) LOOK/C-LOOK — like SCAN/C-SCAN but reverse at the last request, not the disk edge (don't go all the way to the end if no requests are there).",
      howItWorks: "1. Disk geometry: platters, tracks (concentric circles), sectors. The read/write head moves radially (seek) to the right track, then waits for the sector to rotate under it (rotational latency).\n2. Seek time is the dominant cost (moving the head). Scheduling minimizes total seek distance.\n3. FCFS: service in arrival order. Simple, fair. But head jumps around (high total seek).\n4. SSTF: pick the nearest request (by track number). Good throughput. But: requests far from the head can starve if closer ones keep arriving.\n5. SCAN (elevator): the head sweeps in one direction, servicing all requests in order. At the end, reverses. Like an elevator visiting floors.\n6. C-SCAN: like SCAN but only services in one direction (e.g., outward). At the end, jumps back to the start without servicing. Uniform wait times.\n7. LOOK: like SCAN but reverses at the last request in each direction (doesn't go to the disk edge if no requests there). C-LOOK: one direction, jump back.\n8. Modern SSDs: no moving parts, no seek time. Disk scheduling matters less (all positions equally fast). Most OSes use simple FCFS or deadline scheduling for SSDs.",
      codeExamples: [{ lang: "text", code: "Disk Scheduling Example:\n\nHead at track 50. Requests: 98, 183, 37, 122, 14, 124, 65, 67\nDisk has 200 tracks (0-199)\n\nFCFS (arrival order):\n  50 -> 98 -> 183 -> 37 -> 122 -> 14 -> 124 -> 65 -> 67\n  Total seek: 48 + 85 + 146 + 85 + 108 + 110 + 59 + 2 = 644\n\nSSTF (nearest first):\n  50 -> 65 -> 67 -> 37 -> 14 -> 98 -> 122 -> 124 -> 183\n  Total seek: 15 + 2 + 30 + 23 + 84 + 24 + 2 + 59 = 239\n  (better than FCFS, but 14 might starve if\n  more requests near 50 arrive)\n\nSCAN (elevator, moving up first):\n  50 -> 65 -> 67 -> 98 -> 122 -> 124 -> 183 -> [199] -> 37 -> 14\n  Total seek: 149 + (199-183) + (199-37) + (37-14) = 149+16+162+23 = 350\n  (goes to the end, then reverses)\n\nC-SCAN (always up, jump back):\n  50 -> 65 -> 67 -> 98 -> 122 -> 124 -> 183 -> [199] -> [0] -> 14 -> 37\n  Total seek: 149 + 16 + 199 + 37 = 401\n  (uniform wait time for all tracks)\n\nLOOK (reverse at last request, not edge):\n  50 -> 65 -> 67 -> 98 -> 122 -> 124 -> 183 -> 37 -> 14\n  Total seek: 133 + 146 + 23 = 302\n  (better than SCAN — doesn't go to 199)\n\n// Modern SSDs: no seek time, so scheduling\n// matters less. Most use FCFS or deadline.", output: "(disk scheduling)", note: "Disk scheduling minimizes head movement: FCFS (fair, slow), SSTF (nearest, can starve), SCAN (elevator, sweep), C-SCAN (one direction, jump back), LOOK (reverse at last request). SSDs have no seek time, so scheduling matters less." }],
      marginNotes: ["SSTF (Shortest Seek Time First) picks the nearest request, giving good throughput. But requests far from the head can starve if closer ones keep arriving. This is the same starvation problem as SJF scheduling.", "SCAN (elevator algorithm) sweeps back and forth like an elevator. Fair (all requests serviced in each sweep) and efficient (no starvation). LOOK improves on SCAN by reversing at the last request, not the disk edge.", "Modern SSDs have no moving parts — no seek time, no rotational latency. All positions are equally fast. Disk scheduling matters much less for SSDs; most OSes use simple FCFS or deadline scheduling."],
      commonMistakes: ["Using SSTF without considering starvation — requests far from the head can starve if closer ones keep arriving. Use SCAN/LOOK for fairness.", "Thinking disk scheduling matters for SSDs — it doesn't (no seek time). SSDs use simpler scheduling (FCFS, deadline, or NCQ)."],
      relatedTopics: ["File Systems", "I/O Management", "CPU Scheduling & Scheduler"],
      externalLinks: [{ label: "Disk Scheduling (Wiki)", url: "https://en.wikipedia.org/wiki/Disk_scheduling" }],
      mcqs: [{ question: "What is the main problem with SSTF (Shortest Seek Time First)?", options: ["It's too slow", "Starvation — requests far from the head may never be serviced if closer ones keep arriving", "It requires too much memory", "It only works with SSDs"], answer: 1, explanations: ["SSTF is actually fast (minimizes seek).", "Correct — SSTF services the nearest request first, giving good throughput. But requests far from the head can starve if closer ones keep arriving (same as SJF starvation). The fix is SCAN (elevator) or LOOK, which sweep the entire disk so no request starves.", "Memory is not the issue.", "SSTF works with HDDs."], difficulty: "medium" }] },
    { id: "io-management", title: "I/O Management", difficulty: "medium", definition: "The OS manages I/O devices through device drivers, providing a uniform interface to diverse hardware (disks, keyboards, network cards). I/O can be blocking (caller waits) or non-blocking (returns immediately). The OS uses interrupts to avoid polling — the device signals the CPU when data is ready. DMA (Direct Memory Access) lets devices transfer data to memory without CPU involvement, improving throughput.",
      coreUnderstanding: "I/O management is the OS's handling of diverse hardware devices (disks, keyboards, network cards, printers) through device drivers. Device drivers are OS-level code that translates generic I/O requests (read, write) into hardware-specific commands. The OS provides a uniform interface (open, read, write, close) regardless of the device. I/O modes: blocking (caller waits until completion — simple), non-blocking (returns immediately with available data — for polling), asynchronous (notifies on completion via callback/signal — efficient). The OS uses interrupts (hardware signals) to avoid polling (the device signals the CPU when ready). DMA (Direct Memory Access) lets devices transfer data directly to/from memory without CPU involvement, freeing the CPU for other work and improving throughput.",
      howItWorks: "1. Device driver: OS code that knows the device's specific protocol. Translates generic read/write to hardware commands. Each device needs its own driver.\n2. Uniform interface: the OS provides open(), read(), write(), close() for all devices. The driver handles the details. Applications don't need to know the hardware.\n3. I/O modes:\n   a. Blocking: read() waits until data is available. Simple, common for files.\n   b. Non-blocking: read() returns immediately with available data (or EAGAIN if none). For polling or select/poll.\n   c. Asynchronous: read() returns immediately; the OS notifies (callback, signal) when complete. Efficient for high-throughput I/O.\n4. Polling vs interrupts: polling = CPU repeatedly checks if the device is ready (wastes CPU). Interrupts = device signals the CPU when ready (efficient, CPU free to do other work).\n5. DMA: the device transfers data directly to/from memory without CPU involvement. The CPU sets up the transfer, does other work, and gets an interrupt when done. Crucial for high-throughput devices (disks, network cards).\n6. I/O layers: application -> system call -> device driver -> device controller -> hardware.",
      codeExamples: [{ lang: "c", code: "// Blocking I/O (simple, common)\nint fd = open(\"file.txt\", O_RDONLY);\nchar buf[100];\nint n = read(fd, buf, 100);  // blocks until data available\n// ... process buf ...\nclose(fd);\n\n// Non-blocking I/O (for polling)\nint fd = open(\"/dev/tty\", O_RDONLY | O_NONBLOCK);\nint n = read(fd, buf, 100);\nif (n == -1 && errno == EAGAIN) {\n    // no data available yet, do something else\n} else if (n > 0) {\n    // data available, process buf\n}\n\n// Asynchronous I/O (efficient, callback-based)\n// Linux: io_uring or libaio\n// struct iocb cb; aio_read(&cb); // returns immediately\n// // OS calls the callback when done\n\n// Interrupts vs Polling:\n// Polling (BAD for slow devices):\n//   while (!(inb(STATUS_PORT) & READY));  // waste CPU!\n//   data = inb(DATA_PORT);\n\n// Interrupts (GOOD, efficient):\n//   // Device signals CPU when ready\n//   // CPU does other work meanwhile\n//   // OS handler reads the data on interrupt\n\n// DMA (Direct Memory Access):\n//   // Device transfers data to memory directly\n//   // CPU sets up transfer, does other work\n//   // Device sends interrupt when done\n//   // No CPU involvement per byte!", output: "(I/O modes)", note: "I/O management: device drivers translate generic requests to hardware commands. Modes: blocking (wait), non-blocking (return immediately), async (callback). Interrupts avoid polling. DMA transfers data without CPU involvement, improving throughput." }],
      marginNotes: ["DMA (Direct Memory Access) is crucial for high-throughput devices (disks, network cards). Without DMA, the CPU would need to copy every byte (programmed I/O), wasting cycles. With DMA, the device transfers data directly to/from memory — the CPU is free to do other work.", "Interrupts avoid polling: instead of the CPU repeatedly checking if the device is ready (wasting CPU), the device signals the CPU with an interrupt when data is available. The CPU handles other work until the interrupt arrives.", "Device drivers are the bridge between the generic OS interface (read/write) and hardware-specific protocols. Each device needs its own driver. The OS loads drivers dynamically (Linux kernel modules, Windows .sys files)."],
      commonMistakes: ["Using polling for slow devices (keyboard, disk) — wastes CPU. Use interrupts instead (the device signals when ready).", "Forgetting DMA for high-throughput transfers — without DMA, the CPU copies every byte (programmed I/O), severely limiting throughput."],
      relatedTopics: ["Interrupts & Interrupt Handling", "File Systems", "Disk Scheduling Algorithms"],
      externalLinks: [{ label: "I/O (Wiki)", url: "https://en.wikipedia.org/wiki/Input/output" }],
      mcqs: [{ question: "What is the advantage of DMA (Direct Memory Access)?", options: ["It encrypts data", "It lets devices transfer data to/from memory without CPU involvement, freeing the CPU for other work", "It compresses data", "It speeds up the CPU clock"], answer: 1, explanations: ["DMA doesn't encrypt.", "Correct — DMA lets a device (disk, network card) transfer data directly to/from memory without CPU involvement. The CPU sets up the transfer, does other work, and gets an interrupt when done. Without DMA, the CPU would copy every byte (programmed I/O), wasting cycles.", "DMA doesn't compress.", "DMA doesn't change the clock."], difficulty: "medium" }] },
    { id: "interrupts", title: "Interrupts & Interrupt Handling", difficulty: "medium", definition: "An interrupt is a signal that causes the CPU to stop its current task, save state, and execute an interrupt handler. Hardware interrupts come from devices (timer, keyboard, disk). Software interrupts (traps/exceptions) come from the CPU itself (division by zero, page fault, system call). The interrupt vector table maps interrupt numbers to handler addresses. Interrupts are the mechanism for async event handling in the OS.",
      coreUnderstanding: "An interrupt is a signal that causes the CPU to stop its current task, save its state, and execute an interrupt handler. Two types: (1) Hardware interrupts — from external devices (timer, keyboard, disk I/O completion, network packet arrival). Asynchronous (can happen at any time). (2) Software interrupts (traps/exceptions) — from the CPU itself (division by zero, page fault, system call, protection fault). Synchronous (happen at a specific instruction). The interrupt vector table (IVT) or interrupt descriptor table (IDT) maps interrupt numbers to handler addresses. The OS registers handlers for each interrupt type. Interrupts are the mechanism for async event handling: the OS doesn't need to poll devices — they interrupt when ready.",
      howItWorks: "1. Interrupt occurs (hardware signal or CPU exception).\n2. CPU stops the current instruction, saves state (PC, registers) to the stack.\n3. CPU switches to kernel mode (if not already).\n4. CPU looks up the interrupt number in the interrupt vector table (IVT/IDT) to find the handler address.\n5. CPU jumps to the interrupt handler (OS code).\n6. Handler runs: saves more registers, processes the interrupt, restores registers.\n7. Handler executes iret/iretq (interrupt return): restores the saved state and returns to the interrupted instruction.\n8. Hardware interrupts: timer (scheduling), keyboard (input), disk (I/O complete), network (packet arrived).\n9. Software interrupts: division by zero, page fault, system call (int 0x80 or syscall instruction), protection fault.\n10. Interrupt priority: some interrupts can be nested (a higher-priority interrupt can interrupt a lower-priority handler). The OS can disable interrupts (cli instruction) for critical sections.",
      codeExamples: [{ lang: "c", code: "// Interrupt handling (simplified)\n\n// The OS registers handlers in the IDT:\n// IDT[0x80] = syscall_handler;\n// IDT[14]   = page_fault_handler;\n// IDT[0x20] = timer_handler;\n// IDT[0x21] = keyboard_handler;\n\n// Timer interrupt handler (called ~100 times/second)\nvoid timer_handler() {\n    save_registers();\n    // The OS uses this for:\n    //   - Preemptive scheduling (time slice expired?)\n    //   - Updating the system clock\n    //   - Timeout handling\n    schedule();  // maybe switch processes\n    acknowledge_interrupt(0x20);  // tell PIC we're done\n    restore_registers();\n}\n\n// Page fault handler\nvoid page_fault_handler() {\n    unsigned long addr = read_cr2();  // faulting address\n    if (is_valid_address(addr)) {\n        // Load the page from disk\n        int frame = get_free_frame();\n        read_from_disk(addr, frame);\n        update_page_table(addr, frame);\n        // Restart the faulting instruction (iret)\n    } else {\n        // Invalid access -> SIGSEGV (segfault)\n        kill_process(current, SIGSEGV);\n    }\n}\n\n// Hardware interrupt flow:\n// 1. Device sends interrupt signal\n// 2. PIC (Programmable Interrupt Controller) prioritizes\n// 3. CPU stops, saves state, switches to kernel mode\n// 4. CPU looks up handler in IDT\n// 5. Handler runs, acknowledges the interrupt\n// 6. CPU restores state and resumes", output: "(interrupt handling)", note: "Interrupts: hardware (devices: timer, keyboard, disk) or software (CPU exceptions: page fault, division by zero, syscall). The IDT maps interrupt numbers to handlers. CPU saves state, runs handler, restores state. Enables async event handling without polling." }],
      marginNotes: ["The timer interrupt is the heart of preemptive scheduling. The OS sets a timer (e.g., every 10ms). When it fires, the timer handler runs and the scheduler checks if the current process's time slice expired — if so, it switches to the next process.", "Interrupt handlers must be fast (the device may be waiting and other interrupts may be blocked). For slow work (disk I/O), the handler acknowledges the interrupt and defers the real work to a 'bottom half' / softirq / tasklet (processed later with interrupts enabled).", "The OS can disable interrupts (cli instruction on x86) for critical sections where interruption would cause data corruption (e.g., updating a shared data structure). But disabling interrupts for too long causes missed device events. Keep critical sections very short."],
      commonMistakes: ["Doing slow work in interrupt handlers — the handler runs with interrupts disabled (or at elevated priority), blocking other devices. Defer slow work to bottom halves/softirqs.", "Disabling interrupts for too long — causes missed device events (lost keystrokes, dropped packets, missed timer ticks). Keep critical sections very short."],
      relatedTopics: ["I/O Management", "System Calls", "Context Switching"],
      externalLinks: [{ label: "Interrupt (Wiki)", url: "https://en.wikipedia.org/wiki/Interrupt" }],
      mcqs: [{ question: "What is the difference between a hardware interrupt and a software interrupt (trap)?", options: ["Hardware is faster", "Hardware comes from external devices (async); software comes from the CPU itself (sync: exceptions, system calls)", "They are the same", "Hardware is for input only"], answer: 1, explanations: ["Speed is not the key difference.", "Correct — hardware interrupts come from external devices (timer, keyboard, disk) and are asynchronous (can happen at any time). Software interrupts (traps/exceptions) come from the CPU itself (division by zero, page fault, system call) and are synchronous (happen at a specific instruction).", "They are different.", "Hardware interrupts can be for input or output."], difficulty: "medium" }] },
    { id: "fork-exec-wait", title: "fork(), exec(), wait()", difficulty: "medium", definition: "In Unix, fork() creates an exact copy of the calling process (parent and child). exec() replaces the current process's memory image with a new program — it doesn't return on success. wait() makes the parent block until a child exits. This fork-exec-wait pattern is how Unix launches programs: fork to create a child, exec to load the new program, wait to reap the child. The shell does this for every command you run.",
      coreUnderstanding: "The fork-exec-wait pattern is how Unix launches programs. fork() creates an exact copy of the calling process (parent gets child's PID, child gets 0). exec() replaces the current process's memory image (code, data, heap, stack) with a new program — the PID stays the same, but the program changes. exec() doesn't return on success (the old program is gone). wait() makes the parent block until a child exits, then retrieves its exit status. The shell does this for every command: fork (create child), exec (load 'ls' into child), wait (parent shell waits for 'ls' to finish). Copy-on-write (COW) makes fork() fast: parent and child share the same physical pages until one writes (then the page is copied).",
      howItWorks: "1. fork(): creates a child process that is an exact copy of the parent (same code, data, open files, registers). Returns child PID to parent, 0 to child. Copy-on-write (COW): pages are shared until one writes.\n2. exec(program): replaces the current process's memory image with the new program. The PID stays the same, but code/data/heap/stack are replaced. Open file descriptors are inherited (unless close-on-exec is set). Does NOT return on success (the old program is gone). Returns -1 on failure.\n3. wait(&status): parent blocks until a child exits. Retrieves the child's exit status. Prevents zombies (child processes that finished but whose parent hasn't called wait).\n4. Shell pattern: shell -> fork() -> child calls exec('ls') -> parent calls wait() -> child runs 'ls' and exits -> parent's wait() returns -> shell prints prompt.\n5. Zombie process: child finished but parent hasn't called wait() yet. The child's PCB is kept (for the exit status) until the parent calls wait(). If the parent never calls wait(), the zombie persists (resource leak).\n6. Orphan process: parent exits before the child. The child is 'reparented' to init (PID 1), which calls wait() to reap it.",
      codeExamples: [{ lang: "c", code: "#include <stdio.h>\n#include <unistd.h>\n#include <sys/wait.h>\n\nint main() {\n    pid_t pid = fork();  // create a child\n    \n    if (pid < 0) {\n        perror(\"fork failed\");\n        return 1;\n    } else if (pid == 0) {\n        // CHILD PROCESS\n        printf(\"Child: PID=%d\\n\", getpid());\n        \n        // exec: replace this process with 'ls'\n        execlp(\"ls\", \"ls\", \"-la\", NULL);\n        // If exec succeeds, code below NEVER runs\n        // (the process image is replaced)\n        perror(\"exec failed\");  // only on failure\n        return 1;\n    } else {\n        // PARENT PROCESS\n        printf(\"Parent: PID=%d, Child=%d\\n\", getpid(), pid);\n        \n        int status;\n        wait(&status);  // block until child exits\n        \n        if (WIFEXITED(status)) {\n            printf(\"Child exited with %d\\n\", WEXITSTATUS(status));\n        }\n    }\n    return 0;\n}\n\n// Copy-on-Write (COW):\n// fork() doesn't actually copy all pages.\n// Parent and child share the same physical pages\n// (marked read-only). When one writes, the\n// kernel copies that page only (on demand).\n// Makes fork() much faster (especially for\n// large processes that only modify a few pages).\n\n// Zombie: child finished, parent hasn't called wait()\n// The child's PCB is kept for the exit status.\n// $ ps aux | grep Z  # shows zombies\n// Fix: parent must call wait()\n\n// Orphan: parent exited before child\n// Child is reparented to init (PID 1)\n// init calls wait() to reap it", output: "Parent: PID=100, Child=101\nChild: PID=101\ntotal 24\ndrwxr-xr-x  .\n-rw-r--r--  file.txt\n...\nChild exited with 0", note: "fork-exec-wait: fork() creates a child copy (COW makes it fast). exec() replaces the process image with a new program (doesn't return on success). wait() reaps the child (prevents zombies). The shell does this for every command." }],
      marginNotes: ["Copy-on-write (COW) makes fork() fast: parent and child share the same physical pages (marked read-only). When one writes, the kernel copies only that page. For large processes that modify few pages after fork, this is much faster than copying everything.", "Zombie process: child finished but parent hasn't called wait() yet. The child's PCB (process control block) is kept for the exit status. If the parent never calls wait(), zombies persist (resource leak). Fix: always call wait() in the parent.", "Orphan process: parent exits before the child. The child is reparented to init (PID 1), which periodically calls wait() to reap orphans. This prevents zombies from parent-less children."],
      commonMistakes: ["Forgetting to call wait() in the parent — creates zombie processes (children that finished but weren't reaped). Always call wait() or waitpid().", "Checking exec() return value for success — exec() doesn't return on success (the process image is replaced). Code after exec() only runs on failure. Use perror() after exec() to report errors."],
      relatedTopics: ["Processes & Process Control Block", "System Calls", "Process States & Transitions"],
      externalLinks: [{ label: "fork-exec (Wiki)", url: "https://en.wikipedia.org/wiki/Fork%E2%80%93exec" }],
      mcqs: [{ question: "What does exec() do?", options: ["Creates a new process", "Replaces the current process's memory image with a new program (PID stays the same)", "Waits for a child process", "Kills a process"], answer: 1, explanations: ["fork() creates a new process, not exec().", "Correct — exec() replaces the current process's memory image (code, data, heap, stack) with a new program. The PID stays the same, but the program changes. exec() doesn't return on success (the old program is gone). Returns -1 on failure.", "wait() waits for a child.", "kill() kills a process."], difficulty: "medium" }] }
  ]
};